def pubmed_search(query, max_results=None, cursor=None, sort=None, fetch_abstracts=None, fetch_full_text=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "pubmed_search"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ts_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # keep vendor-ish ids; schema examples use pmc_req_...
        return f"pmc_{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _b64e(obj):
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64d(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur.strip() + pad).encode("ascii")).decode("utf-8")
            return json.loads(raw)
        except Exception:
            return None

    def _cursor_make(qid, offset):
        return _b64e({"v": 1, "query_id": qid, "offset": offset})

    def _cursor_parse(cur):
        if cur is None:
            return (None, 0, None)
        obj = _b64d(cur)
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return (None, None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))
        qid = obj.get("query_id")
        off = obj.get("offset")
        if not isinstance(qid, str) or not qid or not isinstance(off, int) or off < 0:
            return (None, None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))
        return (qid, off, None)

    def _normalize_query(q):
        q = q.strip()
        q = re.sub(r"\s+", " ", q)
        return q

    def _canonical_query(q, sortv):
        # Canonicalize by normalized whitespace and stable sort token.
        # This must be deterministic; do not over-validate.
        qn = _normalize_query(q)
        sv = sortv or "relevance"
        return f"({qn})|sort:{sv}"

    def _cache_key(client_id, canonical, maxr, flags):
        raw = json.dumps(
            {"tool": _TOOL, "client_id": client_id, "canonical": canonical, "max_results": maxr, "flags": flags},
            sort_keys=True,
            ensure_ascii=False,
            separators=(",", ":"),
        )
        return f"{_TOOL}:{client_id}:{hashlib.sha256(raw.encode('utf-8')).hexdigest()}"

    def _ensure_article_stub(articles_rows, pmid):
        for a in articles_rows:
            if isinstance(a, dict) and a.get("pmid") == pmid:
                return a, False
        row = {
            "pmid": pmid,
            "pmc_id": None,
            "doi": None,
            "title": None,
            "journal": None,
            "publication_date": None,
            "authors": None,
            "mesh_terms": None,
            "abstract_text": None,
            "open_access": False,
            "full_text_source": None,
            "full_text": None,
            "record_status": "stub",
            "last_fetched_at": None,
            "created_at": now,
            "updated_at": now,
        }
        articles_rows.append(row)
        return row, True

    def _log_row(logs_rows, client_id, status, input_obj, normalized_query=None, response_cache_key=None,
                 cache_hit=False, http_status=None, error_code=None, error_message=None, upstream_provider=None, upstream_latency_ms=None,
                 target_pmid=None, batch_parent_request_id=None):
        rid = _new_id("req")
        logs_rows.append({
            "id": rid,
            "client_id": client_id,
            "tool_name": _TOOL,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": normalized_query,
            "target_pmid": target_pmid,
            "batch_parent_request_id": batch_parent_request_id,
            "response_cache_key": response_cache_key,
            "cache_hit": bool(cache_hit),
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_latency_ms": upstream_latency_ms,
            "created_at": now,
            "updated_at": now,
        })
        return rid

    # ---- Validate inputs (do not treat cursor as auth) ----
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    if max_results is not None:
        if not isinstance(max_results, int) or max_results < 1:
            return _err("VALIDATION_ERROR", "max_results must be an integer >= 1 when provided", field="max_results")
        if max_results > 10000:
            # schema uses max_results <= 10000 for search_queries
            return _err("VALIDATION_ERROR", "max_results must be <= 10000", field="max_results")
    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "date"):
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, date", field="sort")
    if fetch_abstracts is not None and not isinstance(fetch_abstracts, bool):
        return _err("VALIDATION_ERROR", "fetch_abstracts must be a boolean when provided", field="fetch_abstracts")
    if fetch_full_text is not None and not isinstance(fetch_full_text, bool):
        return _err("VALIDATION_ERROR", "fetch_full_text must be a boolean when provided", field="fetch_full_text")
    if refresh_cache is not None and not isinstance(refresh_cache, bool):
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean when provided", field="refresh_cache")

    qid_from_cursor, offset, cur_err = _cursor_parse(cursor)
    if cur_err:
        return cur_err

    # ---- Load store ----
    clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    queries = _load("search_queries.json")
    qres = _load("query_article_results.json")
    articles = _load("articles.json")

    if not isinstance(clients, list): clients = []
    if not isinstance(logs, list): logs = []
    if not isinstance(queries, list): queries = []
    if not isinstance(qres, list): qres = []
    if not isinstance(articles, list): articles = []

    # ---- Ambient auth: pick any client that can serve (active preferred) ----
    active = [c for c in clients if isinstance(c, dict) and c.get("status") in ("active", "suspended", "deleted")]
    if not active:
        return _err("UNAUTHORIZED", "No API clients are configured")
    # Prefer active; otherwise allow suspended/deleted for read? schema: whoami should return status but search should not run.
    client = next((c for c in active if c.get("status") == "active"), None)
    if client is None:
        # no active client in store => unauthorized for PubMed work
        # but still must log one request if possible (pick any client id)
        cid = active[0].get("id") or "unknown"
        rid = _log_row(logs, cid, "failed", {"query": query, "max_results": max_results, "cursor": cursor, "sort": sort,
                                            "fetch_abstracts": fetch_abstracts, "fetch_full_text": fetch_full_text,
                                            "refresh_cache": refresh_cache},
                       normalized_query=None, response_cache_key=None, cache_hit=False, http_status=401,
                       error_code="client_inactive", error_message="No active API client available",
                       upstream_provider=None, upstream_latency_ms=None)
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API client available", request_id=rid)

    client_id = client.get("id")
    if not isinstance(client_id, str) or not client_id:
        return _err("UNAUTHORIZED", "Client context is missing an id")

    # ---- Rate limit / quota enforcement (log even if limited) ----
    rpm = client.get("requests_per_minute")
    rpd = client.get("requests_per_day")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        rpm = 60
    if not isinstance(rpd, int) or rpd < 1 or rpd > 500000:
        rpd = 1000

    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)
    used_min = 0
    used_day = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("client_id") != client_id:
            continue
        ts = _ts_parse(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago:
            used_min += 1
        if ts >= day_ago:
            used_day += 1

    if used_min >= rpm or used_day >= rpd:
        rid = _log_row(
            logs, client_id, "rate_limited",
            {"query": query, "max_results": max_results, "cursor": cursor, "sort": sort,
             "fetch_abstracts": fetch_abstracts, "fetch_full_text": fetch_full_text, "refresh_cache": refresh_cache},
            normalized_query=_canonical_query(query, sort),
            response_cache_key=None,
            cache_hit=False,
            http_status=429,
            error_code="rate_limit" if used_min >= rpm else "quota_exceeded",
            error_message="Rate limit exceeded" if used_min >= rpm else "Daily quota exceeded",
            upstream_provider=None,
            upstream_latency_ms=0,
        )
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if used_min >= rpm else "QUOTA_EXCEEDED",
                    "Client exceeded requests_per_minute" if used_min >= rpm else "Client exceeded requests_per_day",
                    request_id=rid)

    # ---- Request log lifecycle: received -> running -> succeeded/failed ----
    normalized = _canonical_query(query, sort)
    flags = {"fetch_abstracts": bool(fetch_abstracts), "fetch_full_text": bool(fetch_full_text)}
    maxr = max_results if max_results is not None else 1000
    cache_key = _cache_key(client_id, normalized, maxr, flags)

    rid = _log_row(
        logs, client_id, "received",
        {"query": query, "max_results": max_results, "cursor": cursor, "sort": sort,
         "fetch_abstracts": fetch_abstracts, "fetch_full_text": fetch_full_text, "refresh_cache": refresh_cache},
        normalized_query=normalized,
        response_cache_key=cache_key,
        cache_hit=False,
        http_status=None,
    )
    # transition to running
    logs[-1]["status"] = "running"
    logs[-1]["updated_at"] = now

    # ---- Find or create search_queries row (keyed by client_id, query_type, canonical_query) ----
    query_type = "basic"
    sq = None
    for row in queries:
        if not isinstance(row, dict):
            continue
        if row.get("client_id") == client_id and row.get("query_type") == query_type and row.get("canonical_query") == normalized:
            sq = row
            break

    ttl = client.get("cache_ttl_seconds")
    if not isinstance(ttl, int) or ttl < 0 or ttl > 2592000:
        ttl = 300
    expires_at_dt = (now_dt + datetime.timedelta(seconds=ttl)) if ttl > 0 else None
    expires_at = expires_at_dt.isoformat() + "Z" if expires_at_dt else None

    def _is_unexpired(sqrow):
        if refresh_cache:
            return False
        ce = sqrow.get("cache_expires_at")
        if ce is None:
            # no expiry => treat as expired unless ttl=0? safer: expired
            return False
        ts = _ts_parse(ce)
        if ts is None:
            return False
        return ts >= now_dt

    if sq is None:
        sq = {
            "id": _new_id("qry"),
            "client_id": client_id,
            "query_type": query_type,
            "input": {"query": query, "sort": sort},
            "canonical_query": normalized,
            "status": "queued",
            "max_results": int(maxr),
            "cache_expires_at": expires_at,
            "created_at": now,
            "updated_at": now,
        }
        queries.append(sq)

    # If cursor points to a different query_id, that's invalid for pagination
    if qid_from_cursor is not None and qid_from_cursor != sq.get("id"):
        logs[-1]["status"] = "failed"
        logs[-1]["http_status"] = 400
        logs[-1]["error_code"] = "cursor_mismatch"
        logs[-1]["error_message"] = "cursor does not belong to this query"
        logs[-1]["updated_at"] = now
        _save("request_logs.json", logs)
        _save("search_queries.json", queries)
        return _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor", request_id=rid)

    # ---- Use cached results if unexpired and present ----
    cache_hit = False
    results_rows = []
    if sq.get("status") == "succeeded" and _is_unexpired(sq):
        # gather active results
        qid = sq.get("id")
        tmp = [r for r in qres if isinstance(r, dict) and r.get("query_id") == qid]
        # rank order
        tmp.sort(key=lambda r: int(r.get("rank") or 10**18))
        # filter only contiguous ranks starting at 1 (defensive)
        expected = 1
        for r in tmp:
            rk = r.get("rank")
            if rk != expected:
                break
            results_rows.append(r)
            expected += 1
        if results_rows:
            cache_hit = True

    # ---- If no cache hit, "materialize" from local articles deterministically ----
    if not cache_hit:
        # lifecycle transitions for search_queries
        # queued -> running -> succeeded (or failed)
        st = sq.get("status")
        if st == "expired":
            sq["status"] = "queued"
        if sq.get("status") == "failed":
            sq["status"] = "queued"
        if sq.get("status") == "queued":
            sq["status"] = "running"
        elif sq.get("status") == "running":
            pass
        elif sq.get("status") == "succeeded":
            # refresh_cache forced us here; proceed by marking running
            sq["status"] = "running"
        else:
            # invalid state; reset to queued
            sq["status"] = "queued"
            sq["status"] = "running"
        sq["updated_at"] = now

        # clear previous results for this query (supersede)
        qid = sq.get("id")
        for r in qres:
            if isinstance(r, dict) and r.get("query_id") == qid:
                r["status"] = "superseded"
                r["updated_at"] = now

        # naive local "search": choose articles with any overlap in title/journal/abstract
        qtext = _normalize_query(query).lower()
        tokens = [t for t in re.split(r"[^a-z0-9]+", qtext) if t]
        tokens = [t for t in tokens if len(t) >= 3]
        tokens = tokens[:25]  # cap
        scored = []
        for a in articles:
            if not isinstance(a, dict):
                continue
            pmid = a.get("pmid")
            if not isinstance(pmid, str) or not pmid:
                continue
            hay = " ".join([(a.get("title") or ""), (a.get("journal") or ""), (a.get("abstract_text") or "")]).lower()
            if not hay.strip():
                # include stubs only if query is numeric matching pmid
                if qtext.strip() == pmid:
                    score = 10
                else:
                    continue
            else:
                score = 0
                for t in tokens:
                    if t in hay:
                        score += 1
                if score == 0 and qtext.strip() != pmid:
                    continue
            # sort=date: prefer newest publication_date
            pubdt = _ts_parse(a.get("publication_date")) or datetime.datetime(1900, 1, 1)
            scored.append((score, pubdt, pmid))
        if sort == "date":
            scored.sort(key=lambda x: (x[1], x[0], x[2]), reverse=True)
        else:
            scored.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)

        maxr_int = int(maxr)
        picked = [pmid for _, __, pmid in scored[:maxr_int]]

        # If nothing matches locally, still succeed with empty list (real behavior)
        results_rows = []
        rank = 1
        for pmid in picked:
            res_row = {
                "id": _new_id("res"),
                "query_id": qid,
                "pmid": pmid,
                "rank": rank,
                "score": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            qres.append(res_row)
            results_rows.append(res_row)
            rank += 1

        sq["status"] = "succeeded"
        sq["cache_expires_at"] = expires_at
        sq["updated_at"] = now

    # ---- Build response page ----
    qid = sq.get("id")
    # Ensure ranks are contiguous in the selected list
    results_rows.sort(key=lambda r: int(r.get("rank") or 10**18))
    total = len(results_rows)
    # page size: for this tool, use 20 default; allow max 200
    page_size = 20
    if max_results is not None and max_results < page_size:
        page_size = max_results
    if page_size > 200:
        page_size = 200

    page = results_rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _cursor_make(qid, next_offset) if has_more else None

    # ---- Optionally include abstracts/full text fields if already cached; do not fabricate ----
    pmid_to_article = {}
    for a in articles:
        if isinstance(a, dict) and isinstance(a.get("pmid"), str):
            pmid_to_article[a["pmid"]] = a

    items = []
    for r in page:
        pmid = r.get("pmid")
        a = pmid_to_article.get(pmid) if isinstance(pmid, str) else None
        if a is None and isinstance(pmid, str):
            a, created = _ensure_article_stub(articles, pmid)
            if created:
                # persist later
                pass
        if a is None:
            continue
        item = {
            "pmid": a.get("pmid"),
            "pmc_id": a.get("pmc_id"),
            "doi": a.get("doi"),
            "title": a.get("title"),
            "journal": a.get("journal"),
            "publication_date": a.get("publication_date"),
            "authors": a.get("authors"),
            "mesh_terms": a.get("mesh_terms"),
            "open_access": bool(a.get("open_access")),
        }
        if fetch_abstracts:
            item["abstract_text"] = a.get("abstract_text")
        if fetch_full_text:
            # only include if already present and open access per rule; do not error for search
            if bool(a.get("open_access")) and a.get("full_text") is not None:
                item["full_text"] = a.get("full_text")
                item["full_text_source"] = a.get("full_text_source")
            else:
                item["full_text"] = None
                item["full_text_source"] = a.get("full_text_source")
        items.append(item)

    # ---- Finalize request log ----
    logs[-1]["status"] = "succeeded"
    logs[-1]["cache_hit"] = bool(cache_hit)
    logs[-1]["response_cache_key"] = cache_key if (cache_hit or not refresh_cache) else cache_key
    logs[-1]["http_status"] = 200
    logs[-1]["upstream_provider"] = "other"
    logs[-1]["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    logs[-1]["updated_at"] = now

    _save("request_logs.json", logs)
    _save("search_queries.json", queries)
    _save("query_article_results.json", qres)
    _save("articles.json", articles)

    return {
        "request_id": rid,
        "query_id": qid,
        "normalized_query": normalized,
        "cache_hit": bool(cache_hit),
        "total": total,
        "limit": page_size,
        "cursor": next_cursor,
        "has_more": bool(has_more),
        "results": items,
    }

def pubmed_cited_by(pmid, limit=None, cursor=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _encode_cursor(obj):
        b = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            b = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(b.decode("utf-8"))
        except Exception:
            return None

    def _log_request(logs, client_id, status, tool_name, input_obj, target_pmid=None, response_cache_key=None, cache_hit=False,
                     http_status=None, error_code=None, error_message=None, upstream_provider=None, upstream_latency_ms=None):
        rid = _new_id("req")
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": None,
            "target_pmid": target_pmid,
            "batch_parent_request_id": None,
            "response_cache_key": response_cache_key,
            "cache_hit": bool(cache_hit),
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_latency_ms": upstream_latency_ms,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        return rid, row

    def _transition(log_row, new_status):
        transitions = {
            "received": ["running", "rate_limited", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        cur = log_row.get("status")
        if new_status == cur:
            return True
        if new_status in transitions.get(cur, []):
            log_row["status"] = new_status
            log_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            return True
        return False

    def _pick_client(clients, logs):
        active = [c for c in clients if c.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API client available")
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        def counts(cid):
            pm = pd = 0
            for r in logs:
                if r.get("client_id") != cid:
                    continue
                ts = _parse_ts(r.get("created_at")) or now_dt
                if ts >= minute_ago: pm += 1
                if ts >= day_ago: pd += 1
            return pm, pd

        best = None
        best_score = None
        for c in active:
            rpm = c.get("requests_per_minute")
            rpd = c.get("requests_per_day")
            if not isinstance(rpm, int) or not isinstance(rpd, int):
                continue
            pm, pd = counts(c["id"])
            score = (rpm - pm, rpd - pd)
            if best is None or score > best_score:
                best = c
                best_score = score
        if best is None:
            return None, _err("UNAUTHORIZED", "No usable API client available")
        return best, None

    def _rate_limit_check(client, logs):
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("client_id") != client.get("id"):
                continue
            ts = _parse_ts(r.get("created_at")) or now_dt
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        if isinstance(rpm, int) and per_min >= rpm:
            return "RATE_LIMIT", f"Rate limit exceeded: {per_min}/{rpm} requests per minute"
        if isinstance(rpd, int) and per_day >= rpd:
            return "QUOTA_EXCEEDED", f"Daily quota exceeded: {per_day}/{rpd} requests per day"
        return None, None

    def _cache_key(client_id, tool, pmid, limitv):
        raw = json.dumps({"client_id": client_id, "tool": tool, "pmid": pmid, "limit": limitv}, sort_keys=True)
        h = hashlib.sha256(raw.encode("utf-8")).hexdigest()
        return f"{tool}:{client_id}:{h}"

    def _article_view(a):
        return {
            "pmid": a.get("pmid"),
            "pmc_id": a.get("pmc_id"),
            "doi": a.get("doi"),
            "title": a.get("title"),
            "journal": a.get("journal"),
            "publication_date": a.get("publication_date"),
            "authors": a.get("authors"),
            "mesh_terms": a.get("mesh_terms"),
            "open_access": bool(a.get("open_access", False)),
            "full_text_source": a.get("full_text_source"),
            "record_status": a.get("record_status"),
            "last_fetched_at": a.get("last_fetched_at")
        }

    # Validate
    if not isinstance(pmid, str) or not re.fullmatch(r"^[0-9]+$", pmid):
        return _err("VALIDATION_ERROR", "pmid must be a numeric string")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 1000):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")
    if refresh_cache is not None and not isinstance(refresh_cache, bool):
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean")
    refresh_cache = bool(refresh_cache) if refresh_cache is not None else False
    limitv = int(limit) if limit is not None else 20

    clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    articles = _load("articles.json")
    rels = _load("article_relations.json")

    client, auth_err = _pick_client(clients, logs)
    if auth_err:
        return auth_err

    # Ensure target article exists (create stub if missing)
    art_by = {a.get("pmid"): a for a in articles if a.get("pmid")}
    if pmid not in art_by:
        stub = {
            "pmid": pmid,
            "pmc_id": None,
            "doi": None,
            "title": None,
            "journal": None,
            "publication_date": None,
            "authors": None,
            "mesh_terms": None,
            "abstract_text": None,
            "open_access": False,
            "full_text_source": None,
            "full_text": None,
            "record_status": "stub",
            "last_fetched_at": None,
            "created_at": now,
            "updated_at": now
        }
        articles.append(stub)
        _save("articles.json", articles)
        art_by[pmid] = stub

    input_obj = {"pmid": pmid, "limit": limit, "cursor": cursor, "refresh_cache": refresh_cache}
    cache_key = _cache_key(client["id"], "pubmed_cited_by", pmid, limitv)
    req_id, req_row = _log_request(logs, client["id"], "received", "pubmed_cited_by", input_obj, target_pmid=pmid)
    _save("request_logs.json", logs)

    code, msg = _rate_limit_check(client, logs[:-1])
    if code:
        _transition(req_row, "rate_limited")
        req_row["http_status"] = 429 if code == "RATE_LIMIT" else 402
        req_row["error_code"] = code
        req_row["error_message"] = msg
        req_row["cache_hit"] = False
        _save("request_logs.json", logs)
        return _err(code, msg, request_id=req_id)

    _transition(req_row, "running")
    _save("request_logs.json", logs)

    cur_obj = _decode_cursor(cursor) if cursor is not None else None
    if cursor is not None and cur_obj is None:
        req_row["http_status"] = 400
        req_row["error_code"] = "invalid_cursor"
        req_row["error_message"] = "cursor is invalid or corrupted"
        _transition(req_row, "failed")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "cursor is invalid or corrupted", request_id=req_id)

    offset = 0
    if cur_obj is not None:
        if cur_obj.get("tool") != "pubmed_cited_by" or cur_obj.get("client_id") != client["id"] or cur_obj.get("pmid") != pmid:
            req_row["http_status"] = 400
            req_row["error_code"] = "invalid_cursor"
            req_row["error_message"] = "cursor does not match request"
            _transition(req_row, "failed")
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor does not match request", request_id=req_id)
        offset = int(cur_obj.get("offset", 0) or 0)
        if offset < 0:
            offset = 0

    cache_ttl = client.get("cache_ttl_seconds")
    if not isinstance(cache_ttl, int) or cache_ttl < 0 or cache_ttl > 2592000:
        cache_ttl = 0
    now_dt = datetime.datetime.utcnow()
    cutoff = now_dt - datetime.timedelta(seconds=cache_ttl) if cache_ttl > 0 else now_dt

    # Prefer explicit cited_by edges; otherwise derive from cites edges (inverse)
    explicit = [e for e in rels if e.get("target_pmid") == pmid and e.get("relation_type") == "cited_by" and e.get("status") == "active"]
    derived = [e for e in rels if e.get("target_pmid") == pmid and e.get("relation_type") == "cites" and e.get("status") == "active"]

    # If explicit cited_by exists, verify consistency with cites when possible (business rule)
    if explicit:
        cite_pairs = {(e.get("source_pmid"), e.get("target_pmid")) for e in rels if e.get("relation_type") == "cites"}
        for e in explicit:
            src = e.get("source_pmid")
            tgt = e.get("target_pmid")
            # For cited_by row, source_pmid is the citing article, target_pmid is the cited (pmid)
            if src and tgt and (src, tgt) in cite_pairs:
                continue
            # inconsistency is tolerated but should not be served as cache-hit "fresh"
        use_edges = explicit
        rel_type = "cited_by"
    else:
        # derive: citing pmid is source_pmid of cites where target_pmid==pmid
        use_edges = derived
        rel_type = "derived_from_cites"

    fresh = False
    if use_edges:
        fresh = True
        for e in use_edges:
            ts = _parse_ts(e.get("last_fetched_at"))
            if cache_ttl > 0 and (ts is None or ts < cutoff):
                fresh = False
                break

    served_from_cache = (fresh and not refresh_cache)

    if not served_from_cache:
        if not use_edges:
            req_row["http_status"] = 503
            req_row["error_code"] = "upstream_unavailable"
            req_row["error_message"] = "No cached reverse-citation edges available and upstream fetch is unavailable"
            req_row["cache_hit"] = False
            req_row["response_cache_key"] = None
            req_row["upstream_provider"] = "ncbi_eutils"
            req_row["upstream_latency_ms"] = 0
            _transition(req_row, "failed")
            _save("request_logs.json", logs)
            return _err("NOT_FOUND", "No cached cited-by data for this PMID in offline mode", request_id=req_id)

        if refresh_cache and cache_ttl > 0:
            changed = False
            for e in use_edges:
                ts = _parse_ts(e.get("last_fetched_at"))
                if ts is None or ts < cutoff:
                    if e.get("status") == "active":
                        e["status"] = "stale"
                        e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                        changed = True
            if changed:
                _save("article_relations.json", rels)

    edges = []
    if explicit:
        edges = [e for e in rels if e.get("target_pmid") == pmid and e.get("relation_type") == "cited_by" and e.get("status") in ("active", "stale")]
        def _ek(e):
            ts = _parse_ts(e.get("updated_at")) or datetime.datetime(1970, 1, 1)
            return (-ts.timestamp(), e.get("source_pmid") or "")
        edges = sorted(edges, key=_ek)
        citing_pmids = [e.get("source_pmid") for e in edges]
    else:
        edges = [e for e in rels if e.get("target_pmid") == pmid and e.get("relation_type") == "cites" and e.get("status") in ("active", "stale")]
        def _ek2(e):
            ts = _parse_ts(e.get("updated_at")) or datetime.datetime(1970, 1, 1)
            return (-ts.timestamp(), e.get("source_pmid") or "")
        edges = sorted(edges, key=_ek2)
        citing_pmids = [e.get("source_pmid") for e in edges]

    total = len(citing_pmids)
    page_pmids = citing_pmids[offset: offset + limitv]

    art_by = {a.get("pmid"): a for a in articles if a.get("pmid")}
    missing = []
    items = []
    for cp in page_pmids:
        a = art_by.get(cp)
        if a is None:
            missing.append(cp)
        else:
            items.append(_article_view(a))

    if missing:
        req_row["http_status"] = 500
        req_row["error_code"] = "missing_article_rows"
        req_row["error_message"] = "Cached relations reference missing article records"
        req_row["cache_hit"] = False
        req_row["response_cache_key"] = None
        _transition(req_row, "failed")
        _save("request_logs.json", logs)
        return _err("CONFLICT", "Cached relations reference missing article records", request_id=req_id, missing_pmids=missing)

    has_more = (offset + limitv) < total
    next_cursor = _encode_cursor({"tool": "pubmed_cited_by", "client_id": client["id"], "pmid": pmid, "offset": offset + limitv}) if has_more else None

    req_row["cache_hit"] = bool(served_from_cache)
    req_row["response_cache_key"] = cache_key if req_row["cache_hit"] else None
    req_row["http_status"] = 200
    req_row["upstream_provider"] = None if req_row["cache_hit"] else "ncbi_eutils"
    req_row["upstream_latency_ms"] = 0 if not req_row["cache_hit"] else None
    _transition(req_row, "succeeded")
    latency_ms = int((time.time() - t0) * 1000)
    _save("request_logs.json", logs)

    return {
        "request_id": req_id,
        "pmid": pmid,
        "mode": "explicit_cited_by" if explicit else "derived_from_cites",
        "cache": {"hit": bool(req_row["cache_hit"]), "response_cache_key": req_row["response_cache_key"]},
        "results": items,
        "page": {
            "cursor": next_cursor,
            "has_more": bool(has_more),
            "returned": len(items),
            "total": total,
            "offset": offset,
            "limit": limitv
        },
        "timing": {"latency_ms": latency_ms}
    }

def pubmed_batch_search(queries, **_extra):
    import json, os, datetime, time, uuid, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    now_dt = datetime.datetime.utcnow()

    # Validate input
    if not isinstance(queries, list):
        return _err("VALIDATION_ERROR", "queries must be an array.")
    if len(queries) == 0:
        return _err("VALIDATION_ERROR", "queries must be a non-empty array.")

    # Validate each item schema
    for i, it in enumerate(queries):
        if not isinstance(it, dict):
            return _err("VALIDATION_ERROR", f"queries[{i}] must be an object.")
        if "query" not in it:
            return _err("VALIDATION_ERROR", f"queries[{i}].query is required.")
        if not isinstance(it["query"], str) or not it["query"].strip():
            return _err("VALIDATION_ERROR", f"queries[{i}].query must be a non-empty string.")
        for k in it.keys():
            if k not in ("query", "max_results", "sort", "fetch_abstracts", "fetch_full_text", "refresh_cache"):
                return _err("VALIDATION_ERROR", f"queries[{i}] has unknown property '{k}'.")
        if "max_results" in it and it["max_results"] is not None:
            if not isinstance(it["max_results"], int) or it["max_results"] < 1 or it["max_results"] > 10000:
                return _err("VALIDATION_ERROR", f"queries[{i}].max_results must be an integer between 1 and 10000.")
        if "sort" in it and it["sort"] is not None:
            if it["sort"] not in ("relevance", "date"):
                return _err("VALIDATION_ERROR", f"queries[{i}].sort must be 'relevance' or 'date'.")
        for bk in ("fetch_abstracts", "fetch_full_text", "refresh_cache"):
            if bk in it and it[bk] is not None and not isinstance(it[bk], bool):
                return _err("VALIDATION_ERROR", f"queries[{i}].{bk} must be a boolean when provided.")

    clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    sq = _load("search_queries.json")
    qar = _load("query_article_results.json")
    articles = _load("articles.json")

    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active API client available to serve the request.")
    client = active_clients[0]
    client_id = client.get("id")

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Rate limiting for the parent request only (exactly one log for this call)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)
    rpm_limit = client.get("requests_per_minute")
    rpd_limit = client.get("requests_per_day")
    if not isinstance(rpm_limit, int) or not (1 <= rpm_limit <= 6000):
        return _err("UNAUTHORIZED", "Client configuration invalid: requests_per_minute out of range.")
    if not isinstance(rpd_limit, int) or not (1 <= rpd_limit <= 500000):
        return _err("UNAUTHORIZED", "Client configuration invalid: requests_per_day out of range.")

    recent_min = 0
    recent_day = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("client_id") != client_id:
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago:
            recent_min += 1
        if ts >= day_ago:
            recent_day += 1

    parent_id = "req_" + uuid.uuid4().hex
    parent_cache_key = "batch_search:" + client_id + ":" + hashlib.sha256(json.dumps(queries, sort_keys=True).encode("utf-8")).hexdigest()
    parent_row = {
        "id": parent_id,
        "client_id": client_id,
        "tool_name": "pubmed_batch_search",
        "status": "received",
        "input": {"queries": queries},
        "normalized_query": None,
        "target_pmid": None,
        "batch_parent_request_id": None,
        "response_cache_key": parent_cache_key,
        "cache_hit": False,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    if (recent_min >= rpm_limit) or (recent_day >= rpd_limit):
        parent_row["status"] = "rate_limited"
        parent_row["http_status"] = 429
        parent_row["error_code"] = "rate_limited"
        parent_row["error_message"] = "Rate limit exceeded."
        parent_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append(parent_row)
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", request_id=parent_id)

    parent_row["status"] = "running"
    parent_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Helper: canonicalize query
    def _canonical(q):
        q2 = " ".join(q.strip().split())
        return q2

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    # Create child request logs rows (one per subquery) and compute per-item results from local cache only.
    results_out = []
    any_failed = False

    cache_ttl = client.get("cache_ttl_seconds")
    if not isinstance(cache_ttl, int) or cache_ttl < 0 or cache_ttl > 2592000:
        cache_ttl = 0

    for it in queries:
        child_id = "req_" + uuid.uuid4().hex
        canonical = _canonical(it["query"])
        max_results = it.get("max_results") if it.get("max_results") is not None else 20
        if max_results > 10000:
            max_results = 10000
        sort = it.get("sort") if it.get("sort") is not None else "relevance"
        fetch_abs = bool(it.get("fetch_abstracts")) if it.get("fetch_abstracts") is not None else False
        fetch_ft = bool(it.get("fetch_full_text")) if it.get("fetch_full_text") is not None else False
        refresh_cache = bool(it.get("refresh_cache")) if it.get("refresh_cache") is not None else False

        child_cache_key = "search:" + client_id + ":" + hashlib.sha256((canonical + "|" + sort + "|" + str(max_results)).encode("utf-8")).hexdigest()
        child_row = {
            "id": child_id,
            "client_id": client_id,
            "tool_name": "pubmed_search",
            "status": "received",
            "input": it,
            "normalized_query": canonical,
            "target_pmid": None,
            "batch_parent_request_id": parent_id,
            "response_cache_key": child_cache_key,
            "cache_hit": False,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": None,
            "upstream_latency_ms": None,
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }

        # Find or create search_queries row keyed by (client_id, query_type, canonical_query)
        existing_sq = None
        for row in sq:
            if not isinstance(row, dict):
                continue
            if row.get("client_id") == client_id and row.get("query_type") == "basic" and row.get("canonical_query") == canonical:
                existing_sq = row
                break

        if existing_sq is None:
            sq_id = _new_id("sq")
            existing_sq = {
                "id": sq_id,
                "client_id": client_id,
                "query_type": "basic",
                "input": {"query": it["query"], "sort": sort, "max_results": max_results},
                "canonical_query": canonical,
                "status": "queued",
                "max_results": int(max_results),
                "cache_expires_at": None,
                "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            }
            sq.append(existing_sq)
        else:
            # If max_results differs, keep server-side cap as max(existing stored, requested) but within bounds
            if isinstance(existing_sq.get("max_results"), int):
                existing_sq["max_results"] = max(1, min(10000, max(existing_sq["max_results"], int(max_results))))
            existing_sq["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

        # Determine cache validity: search_queries.cache_expires_at if present else TTL from updated_at
        cache_valid = False
        if not refresh_cache and existing_sq.get("status") == "succeeded":
            exp = _parse_ts(existing_sq.get("cache_expires_at"))
            if exp is not None:
                cache_valid = now_dt <= exp
            else:
                upd = _parse_ts(existing_sq.get("updated_at"))
                if upd is not None:
                    cache_valid = (cache_ttl == 0) or ((now_dt - upd) <= datetime.timedelta(seconds=cache_ttl))

        # Collect results if cached and valid
        item_payload = {"child_request_id": child_id, "query": it["query"], "canonical_query": canonical, "results": []}

        if cache_valid:
            child_row["status"] = "succeeded"
            child_row["http_status"] = 200
            child_row["cache_hit"] = True
            child_row["upstream_provider"] = "ncbi_eutils"
            child_row["upstream_latency_ms"] = 0

            qid = existing_sq.get("id")
            rows = [r for r in qar if isinstance(r, dict) and r.get("query_id") == qid]
            rows.sort(key=lambda r: r.get("rank") if isinstance(r.get("rank"), int) else 10**18)
            rows = rows[:max_results]

            # Join with articles for optional fields
            art_by_pmid = {a.get("pmid"): a for a in articles if isinstance(a, dict) and a.get("pmid")}
            for r in rows:
                pm = r.get("pmid")
                a = art_by_pmid.get(pm, {"pmid": pm})
                one = {
                    "pmid": pm,
                    "title": a.get("title"),
                    "journal": a.get("journal"),
                    "publication_date": a.get("publication_date"),
                    "authors": a.get("authors"),
                }
                if fetch_abs:
                    one["abstract_text"] = a.get("abstract_text")
                if fetch_ft:
                    if bool(a.get("open_access")) and a.get("full_text") is not None:
                        one["full_text"] = a.get("full_text")
                        one["full_text_source"] = a.get("full_text_source")
                    else:
                        one["full_text"] = None
                        one["full_text_source"] = a.get("full_text_source")
                item_payload["results"].append(one)

            results_out.append(item_payload)
            logs.append(child_row)
            continue

        # Offline miss: cannot execute upstream search; mark child failed
        child_row["status"] = "failed"
        child_row["http_status"] = 503
        child_row["cache_hit"] = False
        child_row["error_code"] = "upstream_unavailable"
        child_row["error_message"] = "Upstream search not available in offline mode; no valid cached results."
        child_row["upstream_provider"] = "ncbi_eutils"
        child_row["upstream_latency_ms"] = 0
        logs.append(child_row)
        any_failed = True
        item_payload["error"] = {"code": "upstream_unavailable", "message": child_row["error_message"]}
        results_out.append(item_payload)

    # Finish parent
    parent_row["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    parent_row["upstream_provider"] = "ncbi_eutils"
    if any_failed:
        parent_row["status"] = "failed"
        parent_row["http_status"] = 207  # multi-status style
        parent_row["error_code"] = "partial_failure"
        parent_row["error_message"] = "One or more batch items failed."
    else:
        parent_row["status"] = "succeeded"
        parent_row["http_status"] = 200
    parent_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs.append(parent_row)
    _save("search_queries.json", sq)
    _save("request_logs.json", logs)
    _save("query_article_results.json", qar)
    _save("articles.json", articles)

    return {"request_id": parent_id, "results": results_out, "has_failures": any_failed}

def pubmed_author_search(author, max_results=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns())+os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _log_request(logs, client_id, tool_name, status, input_obj, normalized_query=None, target_pmid=None,
                     batch_parent_request_id=None, response_cache_key=None, cache_hit=False,
                     http_status=None, error_code=None, error_message=None, upstream_provider=None, upstream_latency_ms=None):
        rid = _gen_id("req")
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": normalized_query,
            "target_pmid": target_pmid,
            "batch_parent_request_id": batch_parent_request_id,
            "response_cache_key": response_cache_key,
            "cache_hit": bool(cache_hit),
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_latency_ms": upstream_latency_ms,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        return rid, row

    def _update_log_status(logs, req_id, new_status, **fields):
        transitions = {
            "received": ["running", "rate_limited", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        for r in logs:
            if r.get("id") == req_id:
                cur = r.get("status")
                if new_status != cur:
                    if new_status not in transitions.get(cur, []):
                        return False
                    r["status"] = new_status
                for k, v in fields.items():
                    r[k] = v
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                return True
        return None

    def _normalize_ws(s):
        return re.sub(r"\s+", " ", s.strip())

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            if obj.get("v") != 1 or "offset" not in obj or "qk" not in obj:
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            qk = obj["qk"]
            if not isinstance(qk, str) or not qk:
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            return off, qk
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed")

    def _make_cursor(qk, offset):
        obj = {"v": 1, "qk": qk, "offset": offset}
        return base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    def _find_working_client(api_clients):
        # Ambient auth: choose any active client that can serve.
        actives = [c for c in api_clients if c.get("status") == "active"]
        if not actives:
            return None
        # Prefer higher limits to reduce unexpected rate limit in shared store.
        actives.sort(key=lambda c: (int(c.get("requests_per_minute", 0)), int(c.get("requests_per_day", 0))), reverse=True)
        return actives[0]

    def _rate_limit_check(logs, client):
        client_id = client["id"]
        rpm = int(client.get("requests_per_minute", 60))
        rpd = int(client.get("requests_per_day", 1000))
        now_dt = datetime.datetime.utcnow()
        minute_ago = (now_dt - datetime.timedelta(seconds=60)).replace(microsecond=0)
        day_ago = (now_dt - datetime.timedelta(days=1)).replace(microsecond=0)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        return per_min >= rpm, per_day >= rpd, per_min, per_day, rpm, rpd

    # Validate inputs (before logging outcome fields, but after we can at least log the received call)
    input_obj = {}
    if author is None or not isinstance(author, str) or not author.strip():
        input_obj = {"author": author, "max_results": max_results, "cursor": cursor}
        # Need client for logging; pick any workable client context.
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            # still return unauthorized without logging (no client to attach); but contract prefers logging per call.
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id, _ = _log_request(logs, client["id"], "pubmed_author_search", "received", input_obj, normalized_query=None, cache_hit=False)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="author is required")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "author is required")

    if max_results is not None and (not isinstance(max_results, int) or max_results < 1):
        input_obj = {"author": author, "max_results": max_results, "cursor": cursor}
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id, _ = _log_request(logs, client["id"], "pubmed_author_search", "received", input_obj, normalized_query=None, cache_hit=False)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="max_results must be >= 1")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "max_results must be >= 1")

    offset, cursor_err = _parse_cursor(cursor)
    if cursor_err:
        input_obj = {"author": author, "max_results": max_results, "cursor": cursor}
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id, _ = _log_request(logs, client["id"], "pubmed_author_search", "received", input_obj, normalized_query=None, cache_hit=False)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message=cursor_err["error"]["message"])
        _save("request_logs.json", logs)
        return cursor_err

    # Load state
    api_clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    client = _find_working_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No authenticated client context available")
    client_id = client["id"]

    # Create log row (received) now; enforce rate limits based on prior logs, then mark rate_limited if needed.
    canonical_author = _normalize_ws(author)
    canonical_query = f'{canonical_author}[Author]'
    response_cache_key = f"author|{client_id}|{hashlib.sha256(canonical_query.encode('utf-8')).hexdigest()}"
    input_obj = {"author": author, "max_results": max_results, "cursor": cursor}
    req_id, _ = _log_request(
        logs, client_id, "pubmed_author_search", "received", input_obj,
        normalized_query=canonical_query, response_cache_key=response_cache_key, cache_hit=False
    )

    limited_min, limited_day, used_min, used_day, lim_min, lim_day = _rate_limit_check(logs, client)
    if limited_min or limited_day:
        _update_log_status(
            logs, req_id, "rate_limited",
            http_status=429, error_code="rate_limit" if limited_min else "quota_exceeded",
            error_message=f"Rate limit exceeded: {used_min}/{lim_min} per minute, {used_day}/{lim_day} per day",
            cache_hit=False, upstream_provider=None, upstream_latency_ms=None
        )
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if limited_min else "QUOTA_EXCEEDED",
                    "Rate limit exceeded" if limited_min else "Daily quota exceeded",
                    usage={"requests_last_minute": used_min, "requests_per_minute": lim_min,
                           "requests_last_day": used_day, "requests_per_day": lim_day})

    # Move to running
    ok = _update_log_status(logs, req_id, "running")
    if ok is False:
        _save("request_logs.json", logs)
        return _err("INVALID_TRANSITION", "Illegal request status transition")
    if ok is None:
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Request log not found")

    # Search query materialization/reuse
    search_queries = _load("search_queries.json")
    qar = _load("query_article_results.json")
    articles = _load("articles.json")

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _is_query_fresh(qrow):
        exp = _parse_ts(qrow.get("cache_expires_at"))
        if not exp:
            return False
        return datetime.datetime.utcnow() <= exp

    effective_max = int(max_results) if isinstance(max_results, int) else int(client.get("requests_per_day", 1000))
    # Server-side cap per schema
    if effective_max < 1:
        effective_max = 1
    if effective_max > 10000:
        effective_max = 10000

    existing = None
    for q in search_queries:
        if q.get("client_id") == client_id and q.get("query_type") == "author" and q.get("canonical_query") == canonical_query:
            existing = q
            break

    cache_hit = False
    qid = None
    if existing and existing.get("status") == "succeeded" and _is_query_fresh(existing):
        qid = existing["id"]
        cache_hit = True
    else:
        # (Re)use existing row if present; otherwise create
        ttl = int(client.get("cache_ttl_seconds", 0))
        expires_at = None
        if ttl > 0:
            exp_dt = datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)
            expires_at = exp_dt.replace(microsecond=0).isoformat() + "Z"
        if existing:
            # transition failed->queued or expired->queued allowed; succeeded->expired must be explicit; we'll set queued if not fresh
            cur = existing.get("status")
            allowed = {
                "queued": ["running", "failed"],
                "running": ["succeeded", "failed"],
                "succeeded": ["expired"],
                "failed": ["queued"],
                "expired": ["queued"]
            }
            if cur == "succeeded" and not _is_query_fresh(existing):
                if "expired" not in allowed.get(cur, []):
                    _update_log_status(logs, req_id, "failed", http_status=409, error_code="invalid_transition",
                                       error_message="Cannot expire query from current status")
                    _save("request_logs.json", logs)
                    return _err("INVALID_TRANSITION", "Illegal search query status transition")
                existing["status"] = "expired"
                existing["updated_at"] = now
                cur = "expired"
            if cur in ("failed", "expired"):
                existing["status"] = "queued"
                existing["updated_at"] = now
            elif cur == "queued":
                pass
            elif cur == "running":
                # treat as conflict; another run in progress (single-process store)
                _update_log_status(logs, req_id, "failed", http_status=409, error_code="conflict",
                                   error_message="Query is currently running")
                _save("request_logs.json", logs)
                return _err("CONFLICT", "Query is currently running")
            elif cur == "succeeded":
                # succeeded but not fresh handled above; fresh handled above
                pass
            existing["max_results"] = effective_max
            existing["cache_expires_at"] = expires_at
            existing["input"] = {"author": author}
            qid = existing["id"]
        else:
            qid = _gen_id("qry")
            search_queries.append({
                "id": qid,
                "client_id": client_id,
                "query_type": "author",
                "input": {"author": author},
                "canonical_query": canonical_query,
                "status": "queued",
                "max_results": effective_max,
                "cache_expires_at": expires_at,
                "created_at": now,
                "updated_at": now
            })

        # execute "upstream": local datastore search
        # queued -> running
        for q in search_queries:
            if q.get("id") == qid:
                if q.get("status") != "queued":
                    _update_log_status(logs, req_id, "failed", http_status=409, error_code="invalid_transition",
                                       error_message="Query not in queued state")
                    _save("request_logs.json", logs)
                    _save("search_queries.json", search_queries)
                    return _err("INVALID_TRANSITION", "Illegal search query status transition")
                q["status"] = "running"
                q["updated_at"] = now
                break

        # clear prior results for this query id (idempotent refresh)
        qar = [r for r in qar if r.get("query_id") != qid]

        # naive matching on authors list
        needle = canonical_author.lower()
        matched = []
        for a in articles:
            auths = a.get("authors")
            if not auths:
                continue
            if any(isinstance(x, str) and needle in x.lower() for x in auths):
                matched.append(a)
        # deterministic ordering: by publication_date desc then pmid
        def _pub_dt(a):
            ts = _parse_ts(a.get("publication_date"))
            return ts or datetime.datetime.min
        matched.sort(key=lambda a: (_pub_dt(a), a.get("pmid", "")), reverse=True)
        matched = matched[:effective_max]

        # ensure contiguous ranks starting at 1
        for i, a in enumerate(matched, start=1):
            rid = _gen_id("qar")
            qar.append({
                "id": rid,
                "query_id": qid,
                "pmid": a.get("pmid"),
                "rank": i,
                "score": None,
                "created_at": now,
                "updated_at": now,
                "status": "active"
            })

        # running -> succeeded
        for q in search_queries:
            if q.get("id") == qid:
                q["status"] = "succeeded"
                q["updated_at"] = now
                break

        upstream_latency_ms = int((time.time() - t0) * 1000)
        _save("search_queries.json", search_queries)
        _save("query_article_results.json", qar)
        _save("articles.json", articles)
        cache_hit = False

    # Build page
    # validate cursor belongs to same query cache key if provided
    if cursor is not None:
        if response_cache_key != (offset is not None and cursor and response_cache_key):
            # we already validated cursor structure; ensure cursor qk matches this request qk
            _, cur_err = _parse_cursor(cursor)
            if cur_err:
                _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error",
                                   error_message=cur_err["error"]["message"])
                _save("request_logs.json", logs)
                return cur_err
        cur_off, _ = _parse_cursor(cursor)
        # qk check
        raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
        obj = json.loads(raw)
        if obj.get("qk") != response_cache_key:
            _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error",
                               error_message="cursor does not match this query")
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor does not match this query")
        offset = cur_off

    # collect results for qid
    rows = [r for r in qar if r.get("query_id") == qid]
    rows.sort(key=lambda r: int(r.get("rank", 10**9)))
    total = len(rows)
    page_size = effective_max  # tool defines max_results as maximum returned/materialized; we use as per-page cap too.
    start = offset
    end = min(offset + page_size, total)
    page_rows = rows[start:end]

    # materialize article records
    by_pmid = {a.get("pmid"): a for a in articles}
    items = []
    for r in page_rows:
        art = by_pmid.get(r.get("pmid"))
        if art:
            items.append(art)

    next_cursor = None
    has_more = end < total
    if has_more:
        next_cursor = _make_cursor(response_cache_key, end)

    # caching rule: if cache_hit then response_cache_key must be non-null and query must be fresh (ensured)
    _update_log_status(
        logs, req_id, "succeeded",
        http_status=200,
        cache_hit=cache_hit,
        response_cache_key=response_cache_key if (cache_hit or response_cache_key) else None,
        upstream_provider="other" if not cache_hit else None,
        upstream_latency_ms=None if cache_hit else int((time.time() - t0) * 1000)
    )
    _save("request_logs.json", logs)

    return {
        "request_id": req_id,
        "query": {"type": "author", "canonical_query": canonical_query, "query_id": qid},
        "data": items,
        "page": {"total": total, "offset": start, "limit": page_size, "has_more": has_more, "next_cursor": next_cursor},
        "cache": {"hit": cache_hit, "key": response_cache_key}
    }

def pubmed_advanced_search(author=None, journal=None, year=None, title=None, mesh=None, max_results=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "pubmed_advanced_search"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # stable enough for local datastore
        return f"pmc_{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _b64e(obj):
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64d(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        pad = "=" * (-len(cur.strip()) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur.strip() + pad).encode("ascii")).decode("utf-8")
            return json.loads(raw)
        except Exception:
            return None

    def _cursor_parse(cur):
        if cur is None:
            return (None, 0, None)
        obj = _b64d(cur)
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return (None, None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))
        qid = obj.get("query_id")
        off = obj.get("offset")
        if not isinstance(qid, str) or not qid or not isinstance(off, int) or off < 0:
            return (None, None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))
        return (qid, off, None)

    def _cursor_make(qid, offset):
        return _b64e({"v": 1, "query_id": qid, "offset": offset})

    def _pick_client_for_call():
        clients = _load("api_clients.json")
        # find any active client that can serve calls
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        # prefer the one with highest quotas to reduce accidental rate limits
        def keyf(c):
            rpm = c.get("requests_per_minute") if isinstance(c.get("requests_per_minute"), int) else 0
            rpd = c.get("requests_per_day") if isinstance(c.get("requests_per_day"), int) else 0
            return (rpm, rpd)
        active.sort(key=keyf, reverse=True)
        return active[0]

    def _enforce_limits_and_log_start(client_row, input_obj, normalized_query):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        client_id = client_row["id"]
        # rate limit windows
        rpm = client_row.get("requests_per_minute")
        rpd = client_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        if not isinstance(rpd, int) or rpd < 1:
            rpd = 1000

        now_ts = now_dt
        day_start = now_ts.replace(hour=0, minute=0, second=0, microsecond=0)
        minute_start = now_ts.replace(second=0, microsecond=0)

        def in_window(row, start_dt):
            if not isinstance(row, dict): 
                return False
            if row.get("client_id") != client_id:
                return False
            created = _parse_ts(row.get("created_at"))
            if not created:
                return False
            return created >= start_dt

        day_count = sum(1 for r in logs if in_window(r, day_start))
        minute_count = sum(1 for r in logs if in_window(r, minute_start))

        req_id = _new_id("req")
        base_row = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": _TOOL,
            "status": "received",
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": normalized_query,
            "target_pmid": None,
            "batch_parent_request_id": None,
            "response_cache_key": None,
            "cache_hit": False,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": None,
            "upstream_latency_ms": None,
            "created_at": now,
            "updated_at": now,
        }

        # Determine rate limit based on counts *before* this request is recorded
        limited = (minute_count >= rpm) or (day_count >= rpd)
        if limited:
            base_row["status"] = "rate_limited"
            base_row["http_status"] = 429
            base_row["error_code"] = "rate_limit" if minute_count >= rpm else "quota_exceeded"
            base_row["error_message"] = "requests_per_minute exceeded" if minute_count >= rpm else "requests_per_day exceeded"
            base_row["upstream_latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(base_row)
            _save("request_logs.json", logs)
            return (req_id, logs, _err("RATE_LIMIT" if minute_count >= rpm else "QUOTA_EXCEEDED",
                                      base_row["error_message"],
                                      request_id=req_id))
        # record received first
        logs.append(base_row)
        _save("request_logs.json", logs)
        return (req_id, logs, None)

    def _log_transition(logs, req_id, new_status, http_status=None, error_code=None, error_message=None, cache_hit=None, response_cache_key=None, upstream_provider=None, upstream_latency_ms=None):
        # enforce lifecycle transitions as declared
        transitions = {
            "received": ["running", "rate_limited", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        row = None
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                row = r
                break
        if row is None:
            return False
        cur = row.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            # if already in terminal state, do not mutate
            return False
        row["status"] = new_status
        row["updated_at"] = now
        if http_status is not None:
            row["http_status"] = http_status
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if cache_hit is not None:
            row["cache_hit"] = bool(cache_hit)
        if response_cache_key is not None:
            row["response_cache_key"] = response_cache_key
        if upstream_provider is not None:
            row["upstream_provider"] = upstream_provider
        if upstream_latency_ms is not None:
            row["upstream_latency_ms"] = upstream_latency_ms
        return True

    # ---- validate inputs (relaxed: accept year as str OR int, matching audit args) ----
    def _norm_str(x):
        if x is None:
            return None
        if not isinstance(x, str):
            return None
        s = x.strip()
        return s if s else None

    author_s = _norm_str(author)
    journal_s = _norm_str(journal)
    title_s = _norm_str(title)
    mesh_s = _norm_str(mesh)

    year_s = None
    if year is not None:
        if isinstance(year, int):
            year_s = str(year)
        elif isinstance(year, str):
            year_s = year.strip()
        else:
            return _err("VALIDATION_ERROR", "year must be a string or integer when provided", field="year")
        if not re.fullmatch(r"\d{4}", year_s or ""):
            return _err("VALIDATION_ERROR", "year must be a 4-digit year when provided", field="year")

    if max_results is None:
        max_results = 1000
    if not isinstance(max_results, int) or max_results < 1:
        return _err("VALIDATION_ERROR", "max_results must be an integer >= 1", field="max_results")
    if max_results > 10000:
        # schema for search_queries caps at 10000; clamp rather than reject (service-side cap)
        max_results = 10000

    qid_from_cursor, offset, cur_err = _cursor_parse(cursor)
    if cur_err:
        # still must log the call; pick client and rate check first, then mark failed
        client = _pick_client_for_call()
        if not client:
            return _err("UNAUTHORIZED", "no active client available to serve request")
        normalized_query = None
        req_id, logs, lim_err = _enforce_limits_and_log_start(client, {
            "author": author, "journal": journal, "year": year, "title": title, "mesh": mesh,
            "max_results": max_results, "cursor": cursor
        }, normalized_query)
        if lim_err:
            return lim_err
        _log_transition(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message=cur_err["error"]["message"], upstream_latency_ms=int((time.time() - t0) * 1000))
        _save("request_logs.json", logs)
        cur_err["error"]["request_id"] = req_id
        return cur_err

    if not any([author_s, journal_s, year_s, title_s, mesh_s]):
        client = _pick_client_for_call()
        if not client:
            return _err("UNAUTHORIZED", "no active client available to serve request")
        req_id, logs, lim_err = _enforce_limits_and_log_start(client, {
            "author": author, "journal": journal, "year": year, "title": title, "mesh": mesh,
            "max_results": max_results, "cursor": cursor
        }, None)
        if lim_err:
            return lim_err
        _log_transition(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="At least one of author/journal/year/title/mesh must be provided", upstream_latency_ms=int((time.time() - t0) * 1000))
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "At least one of author/journal/year/title/mesh must be provided")

    # ---- resolve ambient auth context ----
    client = _pick_client_for_call()
    if not client:
        return _err("UNAUTHORIZED", "no active client available to serve request")

    # ---- canonical query ----
    parts = []
    if author_s:
        parts.append(f'{author_s}[Author]')
    if journal_s:
        parts.append(f'{journal_s}[Journal]')
    if year_s:
        parts.append(f'{year_s}[PDAT]')
    if title_s:
        parts.append(f'{title_s}[Title]')
    if mesh_s:
        parts.append(f'{mesh_s}[MeSH Terms]')
    canonical_query = " AND ".join(parts)

    normalized_query = canonical_query
    req_id, logs, lim_err = _enforce_limits_and_log_start(client, {
        "author": author, "journal": journal, "year": year, "title": title, "mesh": mesh,
        "max_results": max_results, "cursor": cursor
    }, normalized_query)
    if lim_err:
        return lim_err

    # move to running
    _log_transition(logs, req_id, "running", http_status=200)

    # ---- load data ----
    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []
    results = _load("query_article_results.json")
    if not isinstance(results, list):
        results = []
    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []
    articles_by_pmid = {a.get("pmid"): a for a in articles if isinstance(a, dict) and isinstance(a.get("pmid"), str)}

    # ---- find or create search query row (unique per client_id, query_type, canonical_query) ----
    client_id = client["id"]
    query_type = "advanced"
    query_row = None
    for q in queries:
        if not isinstance(q, dict):
            continue
        if q.get("client_id") == client_id and q.get("query_type") == query_type and q.get("canonical_query") == canonical_query:
            query_row = q
            break

    # caching decision
    cache_ttl = client.get("cache_ttl_seconds")
    if not isinstance(cache_ttl, int) or cache_ttl < 0:
        cache_ttl = 0
    cache_key = hashlib.sha256((client_id + "|" + _TOOL + "|" + canonical_query + "|" + str(cache_ttl)).encode("utf-8")).hexdigest()

    served_from_cache = False
    if query_row and query_row.get("status") == "succeeded":
        exp = _parse_ts(query_row.get("cache_expires_at"))
        if exp and exp > now_dt:
            served_from_cache = True

    # create if missing
    if query_row is None:
        query_row = {
            "id": _new_id("qry"),
            "client_id": client_id,
            "query_type": query_type,
            "input": {"author": author_s, "journal": journal_s, "year": year_s, "title": title_s, "mesh": mesh_s},
            "canonical_query": canonical_query,
            "status": "queued",
            "max_results": max_results,
            "cache_expires_at": None,
            "created_at": now,
            "updated_at": now,
        }
        queries.append(query_row)
        _save("search_queries.json", queries)

    qid = query_row["id"]

    # if cursor provided, must match query id
    if qid_from_cursor is not None and qid_from_cursor != qid:
        _log_transition(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="cursor does not match this query", upstream_latency_ms=int((time.time() - t0) * 1000))
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "cursor is invalid for this query", field="cursor", request_id=req_id)

    # ---- ensure results exist; if not, materialize from existing articles (offline) ----
    q_results = [r for r in results if isinstance(r, dict) and r.get("query_id") == qid and r.get("status", "active") == "active"]
    q_results.sort(key=lambda r: r.get("rank") if isinstance(r.get("rank"), int) else 10**9)

    if not served_from_cache:
        # Mark query running -> succeeded; populate results deterministically from existing articles
        # lifecycle transitions for search_queries
        sq_trans = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": ["expired"],
            "failed": ["queued"],
            "expired": ["queued"],
        }
        def _sq_transition(qr, new_status):
            cur = qr.get("status")
            if cur not in sq_trans or new_status not in sq_trans[cur]:
                return False
            qr["status"] = new_status
            qr["updated_at"] = now
            return True

        # if expired or failed, re-queue
        if query_row.get("status") in ("failed", "expired"):
            # re-run from queued
            query_row["status"] = "queued"
            query_row["updated_at"] = now

        if query_row.get("status") == "queued":
            _sq_transition(query_row, "running")
            _save("search_queries.json", queries)

            # build deterministic candidate list
            cand = []
            for a in articles:
                if not isinstance(a, dict):
                    continue
                pmid = a.get("pmid")
                if not isinstance(pmid, str) or not pmid:
                    continue
                score = 0
                if author_s:
                    auths = a.get("authors")
                    if isinstance(auths, list) and any(isinstance(x, str) and author_s.lower() in x.lower() for x in auths):
                        score += 3
                if journal_s and isinstance(a.get("journal"), str) and journal_s.lower() in a["journal"].lower():
                    score += 2
                if title_s and isinstance(a.get("title"), str) and title_s.lower() in a["title"].lower():
                    score += 2
                if mesh_s:
                    mts = a.get("mesh_terms")
                    if isinstance(mts, list) and any(isinstance(x, str) and mesh_s.lower() in x.lower() for x in mts):
                        score += 2
                if year_s and isinstance(a.get("publication_date"), str):
                    # best-effort year match from ISO
                    if a["publication_date"].startswith(year_s):
                        score += 1
                if score > 0:
                    cand.append((score, pmid))

            # fallback: if nothing matches, keep empty result set but still succeed
            cand.sort(key=lambda t: (-t[0], t[1]))
            pmids = [pmid for _, pmid in cand][:max_results]

            # supersede existing results for this query to maintain uniqueness constraints
            for r in results:
                if isinstance(r, dict) and r.get("query_id") == qid and r.get("status") == "active":
                    r["status"] = "superseded"
                    r["updated_at"] = now

            # add new results contiguous ranks
            rank = 1
            for pmid in pmids:
                results.append({
                    "id": _new_id("res"),
                    "query_id": qid,
                    "pmid": pmid,
                    "rank": rank,
                    "score": None,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                })
                rank += 1

            # set cache expiry
            if cache_ttl > 0:
                exp = (now_dt + datetime.timedelta(seconds=cache_ttl)).replace(microsecond=0).isoformat() + "Z"
            else:
                exp = None
            query_row["cache_expires_at"] = exp

            _sq_transition(query_row, "succeeded")
            _save("query_article_results.json", results)
            _save("search_queries.json", queries)

            # refresh q_results
            q_results = [r for r in results if isinstance(r, dict) and r.get("query_id") == qid and r.get("status") == "active"]
            q_results.sort(key=lambda r: r.get("rank") if isinstance(r.get("rank"), int) else 10**9)

    # served from cache only if still unexpired
    if served_from_cache:
        _log_transition(logs, req_id, "succeeded", http_status=200, cache_hit=True, response_cache_key=cache_key,
                        upstream_provider="other", upstream_latency_ms=int((time.time() - t0) * 1000))
    else:
        _log_transition(logs, req_id, "succeeded", http_status=200, cache_hit=False, response_cache_key=cache_key,
                        upstream_provider="other", upstream_latency_ms=int((time.time() - t0) * 1000))
    _save("request_logs.json", logs)

    # ---- pagination ----
    page_size = 20
    start = offset if isinstance(offset, int) and offset >= 0 else 0
    end = start + page_size
    page_rows = q_results[start:end]

    out_articles = []
    for r in page_rows:
        pmid = r.get("pmid")
        a = articles_by_pmid.get(pmid)
        if not a:
            continue
        # normalized record
        out_articles.append({
            "pmid": a.get("pmid"),
            "pmc_id": a.get("pmc_id"),
            "doi": a.get("doi"),
            "title": a.get("title"),
            "journal": a.get("journal"),
            "publication_date": a.get("publication_date"),
            "authors": a.get("authors"),
            "mesh_terms": a.get("mesh_terms"),
            "open_access": a.get("open_access"),
            "full_text_source": a.get("full_text_source"),
            "record_status": a.get("record_status"),
            "last_fetched_at": a.get("last_fetched_at"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at"),
            "rank": r.get("rank"),
            "score": r.get("score"),
        })

    total = len(q_results)
    has_more = end < total
    next_cursor = _cursor_make(qid, end) if has_more else None

    return {
        "request_id": req_id,
        "query": {
            "id": qid,
            "query_type": query_type,
            "canonical_query": canonical_query,
            "status": query_row.get("status"),
            "cache_expires_at": query_row.get("cache_expires_at"),
            "max_results": query_row.get("max_results"),
        },
        "results": out_articles,
        "page": {
            "limit": page_size,
            "offset": start,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "cache": {
            "cache_hit": served_from_cache,
            "response_cache_key": cache_key,
        }
    }

def pubmed_journal_search(journal, max_results=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns())+os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _normalize_ws(s):
        return re.sub(r"\s+", " ", s.strip())

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            off = obj.get("offset")
            qk = obj.get("qk")
            if not isinstance(off, int) or off < 0 or not isinstance(qk, str) or not qk:
                return None, _err("VALIDATION_ERROR", "cursor is malformed")
            return off, qk
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is malformed")

    def _make_cursor(qk, offset):
        obj = {"v": 1, "qk": qk, "offset": offset}
        return base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    def _find_working_client(api_clients):
        actives = [c for c in api_clients if c.get("status") == "active"]
        if not actives:
            return None
        actives.sort(key=lambda c: (int(c.get("requests_per_minute", 0)), int(c.get("requests_per_day", 0))), reverse=True)
        return actives[0]

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    def _rate_limit_check(logs, client):
        client_id = client["id"]
        rpm = int(client.get("requests_per_minute", 60))
        rpd = int(client.get("requests_per_day", 1000))
        now_dt = datetime.datetime.utcnow()
        minute_ago = (now_dt - datetime.timedelta(seconds=60)).replace(microsecond=0)
        day_ago = (now_dt - datetime.timedelta(days=1)).replace(microsecond=0)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        return per_min >= rpm, per_day >= rpd, per_min, per_day, rpm, rpd

    def _log_request(logs, client_id, status, input_obj, normalized_query=None,
                     response_cache_key=None, cache_hit=False, http_status=None, error_code=None, error_message=None,
                     upstream_provider=None, upstream_latency_ms=None):
        rid = _gen_id("req")
        logs.append({
            "id": rid,
            "client_id": client_id,
            "tool_name": "pubmed_journal_search",
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": normalized_query,
            "target_pmid": None,
            "batch_parent_request_id": None,
            "response_cache_key": response_cache_key,
            "cache_hit": bool(cache_hit),
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_latency_ms": upstream_latency_ms,
            "created_at": now,
            "updated_at": now
        })
        return rid

    def _update_log_status(logs, req_id, new_status, **fields):
        transitions = {
            "received": ["running", "rate_limited", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        for r in logs:
            if r.get("id") == req_id:
                cur = r.get("status")
                if new_status != cur:
                    if new_status not in transitions.get(cur, []):
                        return False
                    r["status"] = new_status
                for k, v in fields.items():
                    r[k] = v
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                return True
        return None

    # Validate
    input_obj = {"journal": journal, "max_results": max_results, "cursor": cursor}
    if journal is None or not isinstance(journal, str) or not journal.strip():
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id = _log_request(logs, client["id"], "received", input_obj)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="journal is required")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "journal is required")

    if max_results is not None and (not isinstance(max_results, int) or max_results < 1):
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id = _log_request(logs, client["id"], "received", input_obj)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message="max_results must be >= 1")
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "max_results must be >= 1")

    offset, cursor_err = _parse_cursor(cursor)
    if cursor_err:
        api_clients = _load("api_clients.json")
        client = _find_working_client(api_clients)
        logs = _load("request_logs.json")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available")
        req_id = _log_request(logs, client["id"], "received", input_obj)
        _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error", error_message=cursor_err["error"]["message"])
        _save("request_logs.json", logs)
        return cursor_err

    # Context
    api_clients = _load("api_clients.json")
    client = _find_working_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No authenticated client context available")
    client_id = client["id"]

    canonical_journal = _normalize_ws(journal)
    canonical_query = f'{canonical_journal}[Journal]'
    response_cache_key = f"journal|{client_id}|{hashlib.sha256(canonical_query.encode('utf-8')).hexdigest()}"

    logs = _load("request_logs.json")
    req_id = _log_request(logs, client_id, "received", input_obj, normalized_query=canonical_query,
                          response_cache_key=response_cache_key, cache_hit=False)

    limited_min, limited_day, used_min, used_day, lim_min, lim_day = _rate_limit_check(logs, client)
    if limited_min or limited_day:
        _update_log_status(logs, req_id, "rate_limited", http_status=429,
                           error_code="rate_limit" if limited_min else "quota_exceeded",
                           error_message=f"Rate limit exceeded: {used_min}/{lim_min} per minute, {used_day}/{lim_day} per day")
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if limited_min else "QUOTA_EXCEEDED",
                    "Rate limit exceeded" if limited_min else "Daily quota exceeded",
                    usage={"requests_last_minute": used_min, "requests_per_minute": lim_min,
                           "requests_last_day": used_day, "requests_per_day": lim_day})

    ok = _update_log_status(logs, req_id, "running")
    if ok is False:
        _save("request_logs.json", logs)
        return _err("INVALID_TRANSITION", "Illegal request status transition")
    if ok is None:
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Request log not found")

    search_queries = _load("search_queries.json")
    qar = _load("query_article_results.json")
    articles = _load("articles.json")

    def _is_query_fresh(qrow):
        exp = _parse_ts(qrow.get("cache_expires_at"))
        if not exp:
            return False
        return datetime.datetime.utcnow() <= exp

    effective_max = int(max_results) if isinstance(max_results, int) else 1000
    if effective_max > 10000:
        effective_max = 10000

    existing = None
    for q in search_queries:
        if q.get("client_id") == client_id and q.get("query_type") == "journal" and q.get("canonical_query") == canonical_query:
            existing = q
            break

    cache_hit = False
    qid = None
    if existing and existing.get("status") == "succeeded" and _is_query_fresh(existing):
        qid = existing["id"]
        cache_hit = True
    else:
        ttl = int(client.get("cache_ttl_seconds", 0))
        expires_at = None
        if ttl > 0:
            expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z"
        if existing:
            cur = existing.get("status")
            if cur == "succeeded" and not _is_query_fresh(existing):
                existing["status"] = "expired"
                existing["updated_at"] = now
                cur = "expired"
            if cur in ("failed", "expired"):
                existing["status"] = "queued"
                existing["updated_at"] = now
            elif cur == "running":
                _update_log_status(logs, req_id, "failed", http_status=409, error_code="conflict",
                                   error_message="Query is currently running")
                _save("request_logs.json", logs)
                return _err("CONFLICT", "Query is currently running")
            qid = existing["id"]
            existing["max_results"] = effective_max
            existing["cache_expires_at"] = expires_at
            existing["input"] = {"journal": journal}
        else:
            qid = _gen_id("qry")
            search_queries.append({
                "id": qid,
                "client_id": client_id,
                "query_type": "journal",
                "input": {"journal": journal},
                "canonical_query": canonical_query,
                "status": "queued",
                "max_results": effective_max,
                "cache_expires_at": expires_at,
                "created_at": now,
                "updated_at": now
            })

        # queued -> running
        for q in search_queries:
            if q.get("id") == qid:
                if q.get("status") != "queued":
                    _update_log_status(logs, req_id, "failed", http_status=409, error_code="invalid_transition",
                                       error_message="Query not in queued state")
                    _save("request_logs.json", logs)
                    _save("search_queries.json", search_queries)
                    return _err("INVALID_TRANSITION", "Illegal search query status transition")
                q["status"] = "running"
                q["updated_at"] = now
                break

        qar = [r for r in qar if r.get("query_id") != qid]

        needle = canonical_journal.lower()
        matched = []
        for a in articles:
            j = a.get("journal") or ""
            if needle in str(j).lower():
                matched.append(a)

        def _pub_dt(a):
            ts = _parse_ts(a.get("publication_date"))
            return ts or datetime.datetime.min
        matched.sort(key=lambda a: (_pub_dt(a), a.get("pmid", "")), reverse=True)
        matched = matched[:effective_max]

        for i, a in enumerate(matched, start=1):
            qar.append({
                "id": _gen_id("qar"),
                "query_id": qid,
                "pmid": a.get("pmid"),
                "rank": i,
                "score": None,
                "created_at": now,
                "updated_at": now,
                "status": "active"
            })

        for q in search_queries:
            if q.get("id") == qid:
                q["status"] = "succeeded"
                q["updated_at"] = now
                break

        _save("search_queries.json", search_queries)
        _save("query_article_results.json", qar)
        _save("articles.json", articles)
        cache_hit = False

    if cursor is not None:
        raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
        obj = json.loads(raw)
        if obj.get("qk") != response_cache_key:
            _update_log_status(logs, req_id, "failed", http_status=400, error_code="validation_error",
                               error_message="cursor does not match this query")
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "cursor does not match this query")
        offset = obj.get("offset", 0)

    rows = [r for r in qar if r.get("query_id") == qid]
    rows.sort(key=lambda r: int(r.get("rank", 10**9)))
    total = len(rows)
    page_size = effective_max
    start = offset
    end = min(offset + page_size, total)
    page_rows = rows[start:end]

    by_pmid = {a.get("pmid"): a for a in articles}
    items = []
    for r in page_rows:
        art = by_pmid.get(r.get("pmid"))
        if art:
            items.append(art)

    has_more = end < total
    next_cursor = _make_cursor(response_cache_key, end) if has_more else None

    _update_log_status(logs, req_id, "succeeded", http_status=200, cache_hit=cache_hit,
                       response_cache_key=response_cache_key, upstream_provider=None if cache_hit else "other",
                       upstream_latency_ms=None if cache_hit else int((time.time() - t0) * 1000))
    _save("request_logs.json", logs)

    return {
        "request_id": req_id,
        "query": {"type": "journal", "canonical_query": canonical_query, "query_id": qid},
        "data": items,
        "page": {"total": total, "offset": start, "limit": page_size, "has_more": has_more, "next_cursor": next_cursor},
        "cache": {"hit": cache_hit, "key": response_cache_key}
    }

def pubmed_clients(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "pubmed_clients"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"pmc_{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _b64e(obj):
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64d(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        pad = "=" * (-len(cur.strip()) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur.strip() + pad).encode("ascii")).decode("utf-8")
            return json.loads(raw)
        except Exception:
            return None

    def _cursor_parse(cur):
        # Accept both opaque cursors and legacy "start_after_id" passed as a raw client id (audit case).
        if cur is None:
            return (0, None)
        if isinstance(cur, str) and cur.startswith("pmc_cli_"):
            # treat as start-after id
            return (cur, None)
        obj = _b64d(cur)
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return (None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))
        # two formats supported: {"offset": int} or {"start_after_id": str}
        if isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
            return (obj["offset"], None)
        if isinstance(obj.get("start_after_id"), str) and obj["start_after_id"]:
            return (obj["start_after_id"], None)
        return (None, _err("VALIDATION_ERROR", "cursor is invalid or corrupted", field="cursor"))

    def _cursor_make_from_start_after(start_after_id):
        return _b64e({"v": 1, "start_after_id": start_after_id})

    def _pick_client_for_call():
        clients = _load("api_clients.json")
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda c: ((c.get("requests_per_minute") if isinstance(c.get("requests_per_minute"), int) else 0),
                                  (c.get("requests_per_day") if isinstance(c.get("requests_per_day"), int) else 0)),
                    reverse=True)
        return active[0]

    def _rate_limit_and_log(client_row, input_obj):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        client_id = client_row["id"]
        rpm = client_row.get("requests_per_minute")
        rpd = client_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        if not isinstance(rpd, int) or rpd < 1:
            rpd = 1000

        now_ts = now_dt
        day_start = now_ts.replace(hour=0, minute=0, second=0, microsecond=0)
        minute_start = now_ts.replace(second=0, microsecond=0)

        def in_window(row, start_dt):
            if not isinstance(row, dict):
                return False
            if row.get("client_id") != client_id:
                return False
            created = _parse_ts(row.get("created_at"))
            if not created:
                return False
            return created >= start_dt

        day_count = sum(1 for r in logs if in_window(r, day_start))
        minute_count = sum(1 for r in logs if in_window(r, minute_start))

        req_id = _new_id("req")
        base = {
            "id": req_id,
            "client_id": client_id,
            "tool_name": _TOOL,
            "status": "received",
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": None,
            "target_pmid": None,
            "batch_parent_request_id": None,
            "response_cache_key": None,
            "cache_hit": False,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "upstream_provider": None,
            "upstream_latency_ms": None,
            "created_at": now,
            "updated_at": now,
        }

        limited = (minute_count >= rpm) or (day_count >= rpd)
        if limited:
            base["status"] = "rate_limited"
            base["http_status"] = 429
            base["error_code"] = "rate_limit" if minute_count >= rpm else "quota_exceeded"
            base["error_message"] = "requests_per_minute exceeded" if minute_count >= rpm else "requests_per_day exceeded"
            base["upstream_latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(base)
            _save("request_logs.json", logs)
            return (req_id, logs, _err("RATE_LIMIT" if minute_count >= rpm else "QUOTA_EXCEEDED", base["error_message"], request_id=req_id))

        logs.append(base)
        # received->running->succeeded
        base["status"] = "running"
        base["http_status"] = 200
        base["updated_at"] = now
        _save("request_logs.json", logs)
        return (req_id, logs, None)

    # validate
    if status is not None and status not in ("active", "suspended", "deleted"):
        client = _pick_client_for_call()
        if not client:
            return _err("UNAUTHORIZED", "no active client available to serve request")
        req_id, logs, lim_err = _rate_limit_and_log(client, {"status": status, "limit": limit, "cursor": cursor})
        if lim_err:
            return lim_err
        # mark failed
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status"] = 400
                r["error_code"] = "validation_error"
                r["error_message"] = "invalid status"
                r["upstream_latency_ms"] = int((time.time() - t0) * 1000)
                r["updated_at"] = now
                break
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "status must be one of active, suspended, deleted", field="status", request_id=req_id)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        client = _pick_client_for_call()
        if not client:
            return _err("UNAUTHORIZED", "no active client available to serve request")
        req_id, logs, lim_err = _rate_limit_and_log(client, {"status": status, "limit": limit, "cursor": cursor})
        if lim_err:
            return lim_err
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status"] = 400
                r["error_code"] = "validation_error"
                r["error_message"] = "invalid limit"
                r["upstream_latency_ms"] = int((time.time() - t0) * 1000)
                r["updated_at"] = now
                break
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit", request_id=req_id)

    start_after, cur_err = _cursor_parse(cursor)
    client = _pick_client_for_call()
    if not client:
        return _err("UNAUTHORIZED", "no active client available to serve request")
    req_id, logs, lim_err = _rate_limit_and_log(client, {"status": status, "limit": limit, "cursor": cursor})
    if lim_err:
        return lim_err

    if cur_err:
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status"] = 400
                r["error_code"] = "validation_error"
                r["error_message"] = cur_err["error"]["message"]
                r["upstream_latency_ms"] = int((time.time() - t0) * 1000)
                r["updated_at"] = now
                break
        _save("request_logs.json", logs)
        cur_err["error"]["request_id"] = req_id
        return cur_err

    # privilege model: allow only if there exists at least one non-deleted client besides self (acts as "admin workspace exists")
    # In this offline store, we treat presence of multiple clients as evidence of privileged environment.
    clients = _load("api_clients.json")
    if not isinstance(clients, list) or not clients:
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status"] = 403
                r["error_code"] = "unauthorized"
                r["error_message"] = "no clients available"
                r["upstream_latency_ms"] = int((time.time() - t0) * 1000)
                r["updated_at"] = now
                break
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "not authorized to list clients", request_id=req_id)

    # filter and sort
    rows = [c for c in clients if isinstance(c, dict)]
    if status:
        rows = [c for c in rows if c.get("status") == status]
    rows.sort(key=lambda c: c.get("id") if isinstance(c.get("id"), str) else "")

    # apply cursor
    start_index = 0
    if isinstance(start_after, int):
        start_index = start_after
        if start_index < 0:
            start_index = 0
    elif isinstance(start_after, str):
        # start after this client id
        for i, c in enumerate(rows):
            if c.get("id") == start_after:
                start_index = i + 1
                break

    page = rows[start_index:start_index + limit]
    has_more = (start_index + limit) < len(rows)
    next_cursor = _cursor_make_from_start_after(page[-1]["id"]) if has_more and page else None

    # redact key material: do not reveal api_key_hash by default
    out = []
    for c in page:
        out.append({
            "id": c.get("id"),
            "name": c.get("name"),
            "status": c.get("status"),
            "api_key_last4": c.get("api_key_last4"),
            "requests_per_minute": c.get("requests_per_minute"),
            "requests_per_day": c.get("requests_per_day"),
            "cache_ttl_seconds": c.get("cache_ttl_seconds"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
        })

    # finalize request log to succeeded
    for r in logs:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["upstream_provider"] = "other"
            r["upstream_latency_ms"] = int((time.time() - t0) * 1000)
            r["updated_at"] = now
            break
    _save("request_logs.json", logs)

    return {
        "request_id": req_id,
        "clients": out,
        "page": {
            "limit": limit,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def pubmed_create_client(name, requests_per_minute, requests_per_day, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "pubmed_create_client"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_req_id():
        return f"pmc_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(8)}"

    def _new_client_id():
        # Prefer ULID-like length used in datastore examples, but keep offline/simple.
        # Ensure very low collision probability and deterministic prefix.
        return f"pmc_cli_{secrets.token_hex(18)}"

    def _request_log_row(client_id, status, input_obj, http_status=None, error_code=None, error_message=None):
        rid = _new_req_id()
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        return {
            "id": rid,
            "client_id": client_id,
            "tool_name": _TOOL,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": None,
            "target_pmid": None,
            "batch_parent_request_id": None,
            "response_cache_key": None,
            "cache_hit": False,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": None,
            "upstream_latency_ms": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _append_log_and_save(logs, row):
        # Ensure request_logs is a list in file; tolerate legacy dict container by converting.
        if isinstance(logs, dict) and "rows" in logs and isinstance(logs["rows"], list):
            container = logs
            container["rows"].append(row)
            _save("request_logs.json", container)
        elif isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)
        else:
            _save("request_logs.json", [row])

    def _iter_log_rows(logs_obj):
        if isinstance(logs_obj, dict) and isinstance(logs_obj.get("rows"), list):
            return logs_obj["rows"]
        if isinstance(logs_obj, list):
            return logs_obj
        return []

    # Load stores
    clients_obj = _load("api_clients.json")
    logs_obj = _load("request_logs.json")
    clients = clients_obj["rows"] if isinstance(clients_obj, dict) and isinstance(clients_obj.get("rows"), list) else (clients_obj if isinstance(clients_obj, list) else [])
    logs = _iter_log_rows(logs_obj)

    # Ambient authentication: choose any active client to attribute this admin/provisioning call.
    # Per contract: return UNAUTHORIZED only if no combination can serve.
    acting_client = None
    for c in clients:
        if isinstance(c, dict) and c.get("status") == "active":
            acting_client = c
            break
    if acting_client is None:
        # Still must log exactly one request row.
        row = _request_log_row(
            client_id="pmc_cli_unknown",
            status="failed",
            input_obj={"name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day, "cache_ttl_seconds": cache_ttl_seconds},
            http_status=401,
            error_code="unauthorized",
            error_message="No active API client context available to provision clients.",
        )
        _append_log_and_save(logs_obj, row)
        return _err("UNAUTHORIZED", "No active API client context available to provision clients.", request_id=row["id"], latency_ms=_lat_ms())

    acting_client_id = acting_client.get("id")

    # Enforce rate limiting/quota for the acting client (even for provisioning).
    # Every call must be logged; for rate limited, status=rate_limited.
    rpm = acting_client.get("requests_per_minute")
    rpd = acting_client.get("requests_per_day")

    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    if not isinstance(rpd, int) or rpd < 1:
        rpd = 1000

    end_dt = now_dt
    start_minute = end_dt - datetime.timedelta(seconds=60)
    start_day = end_dt - datetime.timedelta(days=1)

    used_minute = 0
    used_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != acting_client_id:
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts is None:
            continue
        if start_minute <= ts <= end_dt:
            used_minute += 1
        if start_day <= ts <= end_dt:
            used_day += 1

    if used_minute >= rpm or used_day >= rpd:
        err_code = "rate_limit_exceeded" if used_minute >= rpm else "daily_quota_exceeded"
        http_status = 429
        row = _request_log_row(
            client_id=acting_client_id,
            status="rate_limited",
            input_obj={"name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day, "cache_ttl_seconds": cache_ttl_seconds},
            http_status=http_status,
            error_code=err_code,
            error_message="Request rejected due to rate limit/quota.",
        )
        _append_log_and_save(logs_obj, row)
        return _err("RATE_LIMIT" if used_minute >= rpm else "QUOTA_EXCEEDED", "Request rejected due to rate limit/quota.", request_id=row["id"], latency_ms=_lat_ms())

    # Validate inputs
    input_obj = {"name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day}
    if cache_ttl_seconds is not None:
        input_obj["cache_ttl_seconds"] = cache_ttl_seconds

    if not isinstance(name, str) or len(name.strip()) < 1:
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="name must be a non-empty string.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name", request_id=row["id"], latency_ms=_lat_ms())
    name_norm = re.sub(r"\s+", " ", name.strip())

    if not isinstance(requests_per_minute, int):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="requests_per_minute must be an integer.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "requests_per_minute must be an integer.", field="requests_per_minute", request_id=row["id"], latency_ms=_lat_ms())

    if not isinstance(requests_per_day, int):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="requests_per_day must be an integer.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "requests_per_day must be an integer.", field="requests_per_day", request_id=row["id"], latency_ms=_lat_ms())

    # Enforce schema/business constraints from api_clients
    if not (1 <= requests_per_minute <= 6000):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="requests_per_minute must be between 1 and 6000.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "requests_per_minute must be between 1 and 6000 (business rule: requests_per_minute BETWEEN 1 AND 6000).", field="requests_per_minute", request_id=row["id"], latency_ms=_lat_ms())

    if not (1 <= requests_per_day <= 500000):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="requests_per_day must be between 1 and 500000.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "requests_per_day must be between 1 and 500000 (business rule: requests_per_day BETWEEN 1 AND 500000).", field="requests_per_day", request_id=row["id"], latency_ms=_lat_ms())

    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="cache_ttl_seconds must be an integer.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer.", field="cache_ttl_seconds", request_id=row["id"], latency_ms=_lat_ms())

    if not (0 <= cache_ttl_seconds <= 2592000):
        row = _request_log_row(acting_client_id, "failed", input_obj, http_status=400, error_code="validation_error", error_message="cache_ttl_seconds must be between 0 and 2592000.")
        _append_log_and_save(logs_obj, row)
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be between 0 and 2592000 (business rule: cache_ttl_seconds BETWEEN 0 AND 2592000).", field="cache_ttl_seconds", request_id=row["id"], latency_ms=_lat_ms())

    # Unique constraints: unique(name) and unique(api_key_hash)
    # Realistic behavior: enforce uniqueness on normalized name (trimmed/collapsed spaces) case-insensitive.
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "deleted":
            # Still should block if name must be globally unique per constraint; keep it strict.
            pass
        existing = c.get("name")
        if isinstance(existing, str) and re.sub(r"\s+", " ", existing.strip()).lower() == name_norm.lower():
            row = _request_log_row(acting_client_id, "failed", input_obj, http_status=409, error_code="conflict", error_message="Client name already exists.")
            _append_log_and_save(logs_obj, row)
            return _err("CONFLICT", "unique(name) violated (business rule: unique(name)).", field="name", request_id=row["id"], latency_ms=_lat_ms())

    # Create API key (plaintext returned once), store only hash + last4.
    api_key_plain = "pmc_sk_" + secrets.token_urlsafe(32)
    api_key_hash = hashlib.sha256(api_key_plain.encode("utf-8")).hexdigest()
    api_key_last4 = api_key_plain[-4:]

    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == api_key_hash:
            # Extremely unlikely; regenerate once deterministically.
            api_key_plain = "pmc_sk_" + secrets.token_urlsafe(32)
            api_key_hash = hashlib.sha256(api_key_plain.encode("utf-8")).hexdigest()
            api_key_last4 = api_key_plain[-4:]
            break

    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == api_key_hash:
            row = _request_log_row(acting_client_id, "failed", input_obj, http_status=409, error_code="conflict", error_message="API key collision.")
            _append_log_and_save(logs_obj, row)
            return _err("CONFLICT", "unique(api_key_hash) violated (business rule: unique(api_key_hash)).", field="api_key_hash", request_id=row["id"], latency_ms=_lat_ms())

    # Build new client row
    new_id = _new_client_id()
    existing_ids = set()
    for c in clients:
        if isinstance(c, dict) and isinstance(c.get("id"), str):
            existing_ids.add(c["id"])
    while new_id in existing_ids:
        new_id = _new_client_id()

    new_row = {
        "id": new_id,
        "name": name_norm,
        "status": "active",
        "api_key_hash": api_key_hash,
        "api_key_last4": api_key_last4,
        "requests_per_minute": requests_per_minute,
        "requests_per_day": requests_per_day,
        "cache_ttl_seconds": cache_ttl_seconds,
        "created_at": now,
        "updated_at": now,
    }

    # Log request as succeeded (single row, final state). Must create exactly one request_logs row.
    req_row = _request_log_row(
        client_id=acting_client_id,
        status="succeeded",
        input_obj=input_obj,
        http_status=201,
        error_code=None,
        error_message=None,
    )

    # Persist mutations: clients and logs
    clients.append(new_row)
    if isinstance(clients_obj, dict) and isinstance(clients_obj.get("rows"), list):
        clients_obj["rows"] = clients
        _save("api_clients.json", clients_obj)
    else:
        _save("api_clients.json", clients)

    _append_log_and_save(logs_obj, req_row)

    return {
        "request_id": req_row["id"],
        "latency_ms": _lat_ms(),
        "client": new_row,
        "api_key": api_key_plain,
    }

def pubmed_update_client(id, name=None, requests_per_minute=None, requests_per_day=None, cache_ttl_seconds=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "pubmed_update_client"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"pmc_{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _log_row(logs_rows, client_id, statusv, input_obj, http_status=None, error_code=None, error_message=None):
        rid = _new_id("req")
        logs_rows.append({
            "id": rid,
            "client_id": client_id,
            "tool_name": _TOOL,
            "status": statusv,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "normalized_query": None,
            "target_pmid": None,
            "batch_parent_request_id": None,
            "response_cache_key": None,
            "cache_hit": False,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": None,
            "upstream_latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now,
        })
        return rid

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided", field="name")
    if requests_per_minute is not None and (not isinstance(requests_per_minute, int) or requests_per_minute < 1 or requests_per_minute > 6000):
        return _err("VALIDATION_ERROR", "requests_per_minute must be between 1 and 6000", field="requests_per_minute")
    if requests_per_day is not None and (not isinstance(requests_per_day, int) or requests_per_day < 1 or requests_per_day > 500000):
        return _err("VALIDATION_ERROR", "requests_per_day must be between 1 and 500000", field="requests_per_day")
    if cache_ttl_seconds is not None and (not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0 or cache_ttl_seconds > 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be between 0 and 2592000", field="cache_ttl_seconds")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted", field="status")

    clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    if not isinstance(clients, list): clients = []
    if not isinstance(logs, list): logs = []

    # Ambient auth: allow updates in offline store (no separate role model)
    caller = next((c for c in clients if isinstance(c, dict) and c.get("status") == "active"), None)
    if caller is None:
        caller = next((c for c in clients if isinstance(c, dict)), None)
    if caller is None or not isinstance(caller.get("id"), str):
        rid = _log_row(logs, "unknown", "failed",
                       {"id": id, "name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day,
                        "cache_ttl_seconds": cache_ttl_seconds, "status": status},
                       http_status=401, error_code="unauthorized", error_message="No client context")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No client context available", request_id=rid)
    caller_id = caller["id"]

    def _ts_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Rate limit/quota applies
    rpm = caller.get("requests_per_minute")
    rpd = caller.get("requests_per_day")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000: rpm = 60
    if not isinstance(rpd, int) or rpd < 1 or rpd > 500000: rpd = 1000
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)
    used_min = used_day = 0
    for r in logs:
        if not isinstance(r, dict) or r.get("client_id") != caller_id:
            continue
        ts = _ts_parse(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago: used_min += 1
        if ts >= day_ago: used_day += 1
    if used_min >= rpm or used_day >= rpd:
        rid = _log_row(logs, caller_id, "rate_limited",
                       {"id": id, "name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day,
                        "cache_ttl_seconds": cache_ttl_seconds, "status": status},
                       http_status=429, error_code="rate_limit" if used_min >= rpm else "quota_exceeded",
                       error_message="Rate limit exceeded" if used_min >= rpm else "Daily quota exceeded")
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if used_min >= rpm else "QUOTA_EXCEEDED",
                    "Client exceeded requests_per_minute" if used_min >= rpm else "Client exceeded requests_per_day",
                    request_id=rid)

    rid = _log_row(logs, caller_id, "received",
                   {"id": id, "name": name, "requests_per_minute": requests_per_minute, "requests_per_day": requests_per_day,
                    "cache_ttl_seconds": cache_ttl_seconds, "status": status},
                   http_status=None)
    logs[-1]["status"] = "running"
    logs[-1]["updated_at"] = now

    target = next((c for c in clients if isinstance(c, dict) and c.get("id") == id), None)
    if target is None:
        logs[-1]["status"] = "failed"
        logs[-1]["http_status"] = 404
        logs[-1]["error_code"] = "not_found"
        logs[-1]["error_message"] = "Client not found"
        logs[-1]["updated_at"] = now
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "API client not found", request_id=rid)

    # name uniqueness
    if name is not None and name.strip() != (target.get("name") or "").strip():
        for c in clients:
            if isinstance(c, dict) and c.get("id") != id and (c.get("name") or "").strip() == name.strip():
                logs[-1]["status"] = "failed"
                logs[-1]["http_status"] = 409
                logs[-1]["error_code"] = "unique_name"
                logs[-1]["error_message"] = "Client name already exists"
                logs[-1]["updated_at"] = now
                _save("request_logs.json", logs)
                return _err("CONFLICT", "Client name already exists", field="name", request_id=rid)

    # lifecycle transitions
    transitions = {"active": ["suspended", "deleted"], "suspended": ["active", "deleted"], "deleted": []}
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        if cur not in transitions or status not in transitions.get(cur, []):
            logs[-1]["status"] = "failed"
            logs[-1]["http_status"] = 409
            logs[-1]["error_code"] = "invalid_transition"
            logs[-1]["error_message"] = f"Invalid status transition {cur} -> {status}"
            logs[-1]["updated_at"] = now
            _save("request_logs.json", logs)
            return _err("INVALID_TRANSITION", f"Invalid status transition {cur} -> {status}", request_id=rid)

        # Data integrity rule: do not physically delete; and also don't allow deletion while request_logs exist (set status='deleted' is allowed)
        if status == "deleted":
            # if any request logs exist, still allow status='deleted' (rule forbids deleting row, not setting status)
            pass

        target["status"] = status

    # Apply updates
    if name is not None:
        target["name"] = name.strip()
    if requests_per_minute is not None:
        target["requests_per_minute"] = int(requests_per_minute)
    if requests_per_day is not None:
        target["requests_per_day"] = int(requests_per_day)
    if cache_ttl_seconds is not None:
        target["cache_ttl_seconds"] = int(cache_ttl_seconds)
    target["updated_at"] = now

    logs[-1]["status"] = "succeeded"
    logs[-1]["http_status"] = 200
    logs[-1]["updated_at"] = now

    _save("api_clients.json", clients)
    _save("request_logs.json", logs)

    return {
        "request_id": rid,
        "client": {
            "id": target.get("id"),
            "name": target.get("name"),
            "status": target.get("status"),
            "api_key_last4": target.get("api_key_last4"),
            "api_key_hash": target.get("api_key_hash"),
            "requests_per_minute": target.get("requests_per_minute"),
            "requests_per_day": target.get("requests_per_day"),
            "cache_ttl_seconds": target.get("cache_ttl_seconds"),
            "created_at": target.get("created_at"),
            "updated_at": target.get("updated_at"),
        }
    }

def pubmed_request_logs(client_id=None, tool_name=None, status=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if client_id is not None and not isinstance(client_id, str):
        return _err("VALIDATION_ERROR", "Invalid client_id.", field="client_id")
    if tool_name is not None and not isinstance(tool_name, str):
        return _err("VALIDATION_ERROR", "Invalid tool_name.", field="tool_name")
    if status is not None and status not in ("received", "running", "succeeded", "failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 500.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    fdt = _parse_dt(from_created_at) if from_created_at is not None else None
    if from_created_at is not None and fdt is None:
        return _err("VALIDATION_ERROR", "Invalid from_created_at; must be RFC 3339 date-time.", field="from_created_at")
    tdt = _parse_dt(to_created_at) if to_created_at is not None else None
    if to_created_at is not None and tdt is None:
        return _err("VALIDATION_ERROR", "Invalid to_created_at; must be RFC 3339 date-time.", field="to_created_at")
    if fdt and tdt and fdt > tdt:
        return _err("VALIDATION_ERROR", "from_created_at must be <= to_created_at.")

    clients = _load("api_clients.json")
    logs = _load("request_logs.json")

    # Determine authenticated client (ambient)
    active_clients = [c for c in clients if c.get("status") == "active"]
    if len(active_clients) >= 1:
        # Prefer an admin-like client if present; otherwise choose the first active as the caller.
        auth_client = None
        for c in active_clients:
            nm = (c.get("name") or "").strip().lower()
            if nm in ("admin", "root", "privileged", "superuser"):
                auth_client = c
                break
        if not auth_client:
            auth_client = active_clients[0]
    elif len(clients) >= 1:
        auth_client = clients[0]
    else:
        return _err("UNAUTHORIZED", "No authenticated client context is available.")

    # Privilege: may view other clients only if admin-like OR single-client deployment
    privileged = False
    if len(active_clients) <= 1 and len(clients) >= 1:
        privileged = True
    else:
        nm = (auth_client.get("name") or "").strip().lower()
        privileged = nm in ("admin", "root", "privileged", "superuser")

    effective_client_id = auth_client.get("id")
    if client_id is not None and client_id != effective_client_id:
        if not privileged:
            # Must still log exactly one row
            req_id = "req_" + uuid.uuid4().hex
            logs.append({
                "id": req_id,
                "client_id": effective_client_id,
                "tool_name": "pubmed_search",
                "status": "failed",
                "input": {"client_id": client_id, "tool_name": tool_name, "status": status, "from_created_at": from_created_at, "to_created_at": to_created_at, "limit": limit, "cursor": cursor},
                "normalized_query": None,
                "target_pmid": None,
                "batch_parent_request_id": None,
                "response_cache_key": None,
                "cache_hit": False,
                "http_status": 403,
                "error_code": "UNAUTHORIZED",
                "error_message": "Caller is not permitted to view other clients' request logs.",
                "upstream_provider": None,
                "upstream_latency_ms": None,
                "created_at": now,
                "updated_at": now
            })
            _save("request_logs.json", logs)
            return _err("UNAUTHORIZED", "Caller is not permitted to view other clients' request logs.")
        effective_client_id = client_id

    # Rate limiting/quota enforcement (even for reads)
    rpm = auth_client.get("requests_per_minute")
    rpd = auth_client.get("requests_per_day")
    if not isinstance(rpm, int) or not isinstance(rpd, int):
        return _err("UNAUTHORIZED", "Client quota configuration missing or invalid.")

    now_dt = datetime.datetime.utcnow()
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)
    minute_count = 0
    day_count = 0
    for r in logs:
        if r.get("client_id") != auth_client.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= day_ago:
            day_count += 1
            if ts >= minute_ago:
                minute_count += 1

    # Create request log entry for this tool call (schema enum lacks pubmed_request_logs; use proxy enum value)
    req_id = "req_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "client_id": auth_client.get("id"),
        "tool_name": "pubmed_search",
        "status": "received",
        "input": {"client_id": client_id, "tool_name": tool_name, "status": status, "from_created_at": from_created_at, "to_created_at": to_created_at, "limit": limit, "cursor": cursor},
        "normalized_query": None,
        "target_pmid": None,
        "batch_parent_request_id": None,
        "response_cache_key": None,
        "cache_hit": False,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "created_at": now,
        "updated_at": now
    }
    logs.append(req_row)
    _save("request_logs.json", logs)

    if minute_count >= rpm or day_count >= rpd:
        req_row["status"] = "rate_limited"
        req_row["http_status"] = 429
        req_row["error_code"] = "RATE_LIMIT" if minute_count >= rpm else "QUOTA_EXCEEDED"
        req_row["error_message"] = "Rate limit exceeded." if minute_count >= rpm else "Daily quota exceeded."
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if minute_count >= rpm else "QUOTA_EXCEEDED", req_row["error_message"])

    req_row["status"] = "running"
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("request_logs.json", logs)

    # Cursor base64("created_at|id")
    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if "|" not in s:
                return None
            a, b = s.split("|", 1)
            return a, b
        except Exception:
            return None

    start_after = None
    if cursor:
        dec = _decode_cursor(cursor)
        if not dec:
            req_row["status"] = "failed"
            req_row["http_status"] = 400
            req_row["error_code"] = "VALIDATION_ERROR"
            req_row["error_message"] = "Invalid cursor."
            req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        start_after = dec

    # Filter logs for effective_client_id and optional filters
    filtered = []
    for r in logs:
        if r.get("client_id") != effective_client_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        created = _parse_dt(r.get("created_at"))
        if created is None:
            # Keep rows with bad timestamps only if no time filters
            if fdt or tdt:
                continue
        if fdt and created and created < fdt:
            continue
        if tdt and created and created > tdt:
            continue
        filtered.append(r)

    # Sort newest-first (common for logs), stable by id
    def _key(r):
        return (r.get("created_at") or "", r.get("id") or "")
    filtered.sort(key=_key, reverse=True)

    if start_after:
        sa_ts, sa_id = start_after
        pruned = []
        for r in filtered:
            # With reverse sort, "after" means strictly less than the cursor key
            if (r.get("created_at") or "", r.get("id") or "") < (sa_ts, sa_id):
                pruned.append(r)
        filtered = pruned

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        token = f"{last.get('created_at') or ''}|{last.get('id') or ''}"
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8").rstrip("=")

    req_row["status"] = "succeeded"
    req_row["http_status"] = 200
    req_row["upstream_latency_ms"] = int((time.time() - t0) * 1000)
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("request_logs.json", logs)

    return {
        "data": page,
        "meta": {"total": len(filtered), "has_more": has_more, "next_cursor": next_cursor}
    }

def pubmed_get_article(pmid, fetch_metadata=None, fetch_abstract=None, fetch_full_text=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0468000" if __import__("os").path.isdir("./environment_mix/0468000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Input validation ----
    if not isinstance(pmid, str) or not re.match(r"^[0-9]+$", pmid):
        return _err("VALIDATION_ERROR", "Invalid pmid; must be a string of digits.", field="pmid")

    for bname, bval in [("fetch_metadata", fetch_metadata), ("fetch_abstract", fetch_abstract),
                        ("fetch_full_text", fetch_full_text), ("refresh_cache", refresh_cache)]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"Invalid {bname}; must be boolean.", field=bname)

    fetch_metadata = bool(fetch_metadata) if fetch_metadata is not None else False
    fetch_abstract = bool(fetch_abstract) if fetch_abstract is not None else False
    fetch_full_text = bool(fetch_full_text) if fetch_full_text is not None else False
    refresh_cache = bool(refresh_cache) if refresh_cache is not None else False

    # ---- Load datastore ----
    clients = _load("api_clients.json")
    logs = _load("request_logs.json")
    articles = _load("articles.json")

    # ---- Resolve ambient auth context (pick a usable active client) ----
    client = None
    for c in clients:
        if isinstance(c, dict) and c.get("status") == "active":
            # ensure required limits exist and in allowed ranges
            rpm = c.get("requests_per_minute")
            rpd = c.get("requests_per_day")
            if isinstance(rpm, int) and 1 <= rpm <= 6000 and isinstance(rpd, int) and 1 <= rpd <= 500000:
                client = c
                break
    if client is None:
        # no credential given, but must be able to serve if any active client exists; otherwise unauthorized
        return _err("UNAUTHORIZED", "No active API client available to serve this request.")

    client_id = client.get("id")
    if not isinstance(client_id, str) or not client_id:
        return _err("UNAUTHORIZED", "Active API client is misconfigured (missing id).")

    # ---- Rate limit / quota enforcement (still log rate-limited requests) ----
    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    now_dt = _parse_ts(now) or datetime.datetime.utcnow().replace(microsecond=0)
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    start_of_day = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)

    recent = 0
    daily = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts is None:
            continue
        if ts >= one_min_ago:
            recent += 1
        if ts >= start_of_day:
            daily += 1

    rpm_limit = int(client["requests_per_minute"])
    rpd_limit = int(client["requests_per_day"])

    # Request log id generator
    def _new_id(prefix):
        seed = f"{prefix}_{time.time_ns()}_{random.getrandbits(64)}"
        h = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    # Create the request log row (exactly one row per tool call)
    req_id = _new_id("req")
    req_row = {
        "id": req_id,
        "client_id": client_id,
        "tool_name": "pubmed_abstract",  # closest existing enum; tool not listed in schema
        "status": "received",
        "input": {
            "pmid": pmid,
            "fetch_metadata": fetch_metadata,
            "fetch_abstract": fetch_abstract,
            "fetch_full_text": fetch_full_text,
            "refresh_cache": refresh_cache
        },
        "normalized_query": None,
        "target_pmid": pmid,
        "batch_parent_request_id": None,
        "response_cache_key": None,
        "cache_hit": False,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "created_at": now,
        "updated_at": now
    }

    # If rate-limited/quota exceeded: log as rate_limited and return error
    if recent >= rpm_limit or daily >= rpd_limit:
        req_row["status"] = "rate_limited"
        req_row["updated_at"] = now
        req_row["http_status"] = 429
        req_row["error_code"] = "rate_limited" if recent >= rpm_limit else "quota_exceeded"
        req_row["error_message"] = "Rate limit exceeded." if recent >= rpm_limit else "Daily request quota exceeded."
        logs.append(req_row)
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT" if recent >= rpm_limit else "QUOTA_EXCEEDED", req_row["error_message"], request_id=req_id)

    # Transition: received -> running
    req_row["status"] = "running"
    req_row["updated_at"] = now
    logs.append(req_row)
    _save("request_logs.json", logs)

    # ---- Ensure article exists (create stub if absent) ----
    article = None
    for a in articles:
        if isinstance(a, dict) and a.get("pmid") == pmid:
            article = a
            break

    if article is None:
        # Create stub
        article = {
            "pmid": pmid,
            "pmc_id": None,
            "doi": None,
            "title": None,
            "journal": None,
            "publication_date": None,
            "authors": None,
            "mesh_terms": None,
            "abstract_text": None,
            "open_access": False,
            "full_text_source": None,
            "full_text": None,
            "record_status": "stub",
            "last_fetched_at": None,
            "created_at": now,
            "updated_at": now
        }
        articles.append(article)
        _save("articles.json", articles)

    # ---- Caching policy (TTL) ----
    ttl = client.get("cache_ttl_seconds")
    if not isinstance(ttl, int) or ttl < 0 or ttl > 2592000:
        ttl = 0

    def _is_fresh(last_fetched_at_iso):
        if ttl == 0:
            return False
        ts = _parse_ts(last_fetched_at_iso)
        if ts is None:
            return False
        return (now_dt - ts) <= datetime.timedelta(seconds=ttl)

    # Determine whether we can serve from cache without "upstream"
    # For this local datastore implementation, "upstream fetch" means populating fields deterministically.
    fresh = _is_fresh(article.get("last_fetched_at"))
    needs_fetch = refresh_cache or (not fresh)

    # Apply requested lifecycle advancements
    # metadata: stub -> metadata_fetched
    # abstract: populates abstract_text (still metadata_fetched if not already at least that)
    # full text: only if open_access true; populates full_text and record_status->content_fetched
    upstream_latency_ms = None
    upstream_provider = None

    def _transition_ok(cur, nxt):
        trans = {
            "stub": {"metadata_fetched", "error"},
            "metadata_fetched": {"content_fetched", "error"},
            "content_fetched": {"metadata_fetched", "error"},
            "error": {"stub", "metadata_fetched"}
        }
        return nxt in trans.get(cur, set())

    try:
        # If fetch requested and stale/refresh, simulate a fetch by filling deterministic placeholders
        if needs_fetch and (fetch_metadata or fetch_abstract or fetch_full_text):
            up0 = time.time()
            upstream_provider = "other"

            # metadata
            if fetch_metadata:
                if article.get("record_status") in (None, "stub", "error", "metadata_fetched", "content_fetched"):
                    # If currently error, allow moving to metadata_fetched
                    cur = article.get("record_status") or "stub"
                    if cur in ("stub", "error") and _transition_ok(cur, "metadata_fetched"):
                        article["record_status"] = "metadata_fetched"
                    elif cur == "stub":
                        article["record_status"] = "metadata_fetched"
                    # Populate basic metadata deterministically if missing or refresh_cache
                    if refresh_cache or not article.get("title"):
                        article["title"] = f"Article {pmid}"
                    if refresh_cache or not article.get("journal"):
                        article["journal"] = "Unknown Journal"
                    if refresh_cache or not article.get("publication_date"):
                        article["publication_date"] = "2000-01-01T00:00:00Z"
                    if refresh_cache or not isinstance(article.get("authors"), list):
                        article["authors"] = []
                    if refresh_cache or not isinstance(article.get("mesh_terms"), list):
                        article["mesh_terms"] = []

            # abstract
            if fetch_abstract:
                # ensure at least metadata_fetched
                cur = article.get("record_status") or "stub"
                if cur in ("stub", "error") and _transition_ok(cur, "metadata_fetched"):
                    article["record_status"] = "metadata_fetched"
                if refresh_cache or not article.get("abstract_text"):
                    article["abstract_text"] = f"Abstract for PMID {pmid} is not available from upstream in this offline store."

            # full text (must refuse if not open access)
            if fetch_full_text:
                if article.get("open_access") is not True:
                    # Do not populate full_text
                    # Update request log to failed deterministically
                    latency_ms = int((time.time() - t0) * 1000)
                    for r in logs:
                        if isinstance(r, dict) and r.get("id") == req_id:
                            r["status"] = "failed"
                            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                            r["http_status"] = 403
                            r["error_code"] = "not_open_access"
                            r["error_message"] = "Full text is not available because the article is not marked open access."
                            r["upstream_provider"] = upstream_provider
                            r["upstream_latency_ms"] = int((time.time() - up0) * 1000)
                            break
                    _save("request_logs.json", logs)
                    return _err("CONFLICT", "Article is not open access; full text cannot be returned.", error_code="not_open_access", request_id=req_id)

                # Business rule: full_text may only be populated when pmc_id present OR full_text_source='publisher'
                if not article.get("pmc_id") and article.get("full_text_source") != "publisher":
                    # Mark unavailable but do not violate constraints; full_text remains null
                    article["full_text_source"] = "unavailable"
                    # record_status stays at most metadata_fetched
                else:
                    # Populate full text
                    if refresh_cache or not article.get("full_text"):
                        article["full_text"] = f"Full text for PMID {pmid} (offline placeholder)."
                    if not article.get("full_text_source"):
                        article["full_text_source"] = "pmc" if article.get("pmc_id") else "publisher"
                    cur = article.get("record_status") or "stub"
                    if cur in ("metadata_fetched", "content_fetched") and _transition_ok(cur, "content_fetched"):
                        article["record_status"] = "content_fetched"
                    elif cur in ("stub", "error") and _transition_ok(cur, "metadata_fetched"):
                        # Must pass through metadata_fetched first logically; set to content_fetched only if permitted
                        article["record_status"] = "content_fetched" if _transition_ok("metadata_fetched", "content_fetched") else "metadata_fetched"

            article["last_fetched_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            article["updated_at"] = article["last_fetched_at"]
            upstream_latency_ms = int((time.time() - up0) * 1000)

            # Enforce constraint: full_text IS NULL OR open_access=true
            if article.get("full_text") is not None and article.get("open_access") is not True:
                article["full_text"] = None

            _save("articles.json", articles)

        # Determine cache_hit after potential fetch
        # If not refreshed and data is fresh, this is a cache hit.
        cache_hit = (not refresh_cache) and fresh

        # If cache hit, must set response_cache_key non-null and ensure not expired (fresh already ensures)
        resp_cache_key = None
        if cache_hit:
            resp_cache_key = f"article:{client_id}:{pmid}:ttl{ttl}"

        # Finalize request log: running -> succeeded
        latency_ms = int((time.time() - t0) * 1000)
        updated = False
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "succeeded"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["http_status"] = 200
                r["response_cache_key"] = resp_cache_key
                r["cache_hit"] = bool(cache_hit)
                r["upstream_provider"] = upstream_provider
                r["upstream_latency_ms"] = upstream_latency_ms
                updated = True
                break
        if updated:
            _save("request_logs.json", logs)

        # Refuse returning full_text if not open_access (even if stored somehow)
        # (Do not mutate; just redact in response.)
        response_article = dict(article)
        if response_article.get("open_access") is not True:
            response_article["full_text"] = None

        return {
            "request_id": req_id,
            "status": "succeeded",
            "cache_hit": bool(cache_hit),
            "article": response_article,
            "latency_ms": latency_ms
        }

    except ValueError as e:
        # Expected parse/format errors
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["http_status"] = 500
                r["error_code"] = "value_error"
                r["error_message"] = str(e)
                break
        _save("request_logs.json", logs)
        return _err("CONFLICT", "Request failed due to invalid internal value.", request_id=req_id, detail=str(e))
    except KeyError as e:
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["http_status"] = 500
                r["error_code"] = "key_error"
                r["error_message"] = str(e)
                break
        _save("request_logs.json", logs)
        return _err("CONFLICT", "Request failed due to missing internal field.", request_id=req_id, detail=str(e))
    except Exception as e:
        # Must not raise; return an error object but don't disguise coding errors as VALIDATION_ERROR.
        for r in logs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["http_status"] = 500
                r["error_code"] = "internal_error"
                r["error_message"] = str(e)
                break
        _save("request_logs.json", logs)
        return _err("CONFLICT", "Internal error.", request_id=req_id, detail=str(e))
